if (!marked || !target || !resourceTarget) { $done({}); } else { $done({ body: "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\n9901803\n00:00:33.793 --> 00:00:35.873 align:middle line:85%,start position:50%,middle\nGitHub：rexchen1803\n\n1\n00:00:35.953 --> 00:00:39.456\n在得克萨斯州的比格莱克\n流传着这么一个故事\n\n2\n00:00:40.290 --> 00:00:42.709\n关于该市起源的故事\n\n3\n00:00:43.210 --> 00:00:46.171\n这个故事涉及圣丽塔1号\n\n4\n00:00:46.505 --> 00:00:49.508\n西得克萨斯州石油的发源地\n\n5\n00:00:49.967 --> 00:00:54.304\n正如多数得克萨斯传奇一样\n以前有个人认为\n\n6\n00:00:54.388 --> 00:00:56.765\n石油就在他脚下\n\n7\n00:00:57.766 --> 00:01:00.227\n也正如多数这类故事一样\n\n8\n00:01:00.686 --> 00:01:02.271\n没人相信他\n\n9\n00:01:06.191 --> 00:01:08.902\n但是这个故事中有两位修女\n\n10\n00:01:09.486 --> 00:01:12.865\n在1923年遇见了他\n\n11\n00:01:12.948 --> 00:01:16.201\n她们十分相信他和他的梦想\n\n12\n00:01:16.618 --> 00:01:19.788\n甚至给他投资了钱\n没人知道她们这样做了\n\n13\n00:01:28.422 --> 00:01:31.383\n当她们告诉教区的神父\n\n14\n00:01:31.466 --> 00:01:34.887\n那个人的梦想以及她们投资的事实后\n\n15\n00:01:35.846 --> 00:01:39.808\n神父建议她们把钱要回来\n\n16\n00:01:39.892 --> 00:01:43.353\n她们难为情地承认 为时已晚\n\n17\n00:01:43.437 --> 00:01:45.856\n钱已经被花了\n\n18\n00:01:47.733 --> 00:01:49.735\n神父叹了一口气\n\n19\n00:01:49.818 --> 00:01:54.114\n摇了摇头 给出了一个小小的建议\n\n20\n00:01:55.991 --> 00:01:59.494\n用玫瑰花瓣为那个地方祈福\n\n21\n00:01:59.578 --> 00:02:02.206\n祈求圣丽塔的帮助\n\n22\n00:02:02.873 --> 00:02:06.668\n圣丽塔是遥不可及梦想的守护神\n\n23\n00:02:16.845 --> 00:02:21.600\n当工人们等待\n最终可能挖掘出的石油时\n\n24\n00:02:21.683 --> 00:02:23.602\n他们打棒球消磨时间\n\n25\n00:02:24.603 --> 00:02:25.938\n他出局了\n\n26\n00:02:26.021 --> 00:02:29.149\n他们打得很好\n有人甚至得以摆脱灰尘与绝望\n\n27\n00:02:29.233 --> 00:02:33.654\n去职业棒球大联盟打比赛\n\n28\n00:02:33.737 --> 00:02:37.032\n那是鲁斯和格里克的光辉岁月\n\n29\n00:03:16.071 --> 00:03:20.534\n我在许多场合都听过也讲过这个故事\n\n30\n00:03:20.617 --> 00:03:25.581\n但那是很久以前的事了\n\n31\n00:03:25.664 --> 00:03:27.583\n很久之后 圣丽塔决定\n再次降福于这个小城\n\n32\n00:03:29.918 --> 00:03:31.086\n耶！\n\n33\n00:03:36.956 --> 00:03:39.262\n<i>康涅狄格州格罗顿</i>\n\n34\n00:03:39.342 --> 00:03:40.654\n大联盟的第一场比赛\n\n35\n00:03:41.847 --> 00:03:44.558\n吉米·莫里斯有一局无安打赛局\n\n36\n00:03:48.687 --> 00:03:51.857\n吉米 不要投得这么用力 我的手很冷\n\n37\n00:03:58.530 --> 00:04:00.240\n-你在干嘛？\n-等春天到来\n\n38\n00:04:00.324 --> 00:04:02.284\n我就是在等\n\n39\n00:04:02.367 --> 00:04:05.078\n吉米？我和你爸爸想和你谈谈\n\n40\n00:04:09.208 --> 00:04:11.335\n我听说弗吉尼亚很不错\n\n41\n00:04:12.961 --> 00:04:16.548\n至少海军的人是这么跟你你爸爸说的\n\n42\n00:04:16.632 --> 00:04:20.594\n-对吧 吉姆？\n-我们又要搬家了\n\n43\n00:04:20.677 --> 00:04:24.348\n我的工作决定我们什么时候会搬家\n你要做的是努力适应\n\n44\n00:04:24.431 --> 00:04:26.141\n吉姆？别这样\n\n45\n00:04:28.769 --> 00:04:32.814\n谁知道呢？\n也许弗吉尼亚不会下这么多雪\n\n46\n00:04:32.898 --> 00:04:34.274\n吉米·莫里斯\n\n47\n00:04:34.358 --> 00:04:37.486\n再打一场精彩的投球表演\n\n48\n00:04:38.403 --> 00:04:42.699\n就能去争夺世界职业棒球赛冠军了\n\n49\n00:04:47.890 --> 00:04:51.233\n<i>弗吉尼亚州罗阿诺克</i>\n\n50\n00:04:59.174 --> 00:05:03.053\n吉米 我和你爸爸想和你谈谈\n\n51\n00:05:07.465 --> 00:05:10.756\n<i>佛罗里达州好莱坞</i>\n\n52\n00:05:36.879 --> 00:05:38.714\n三振出局！\n\n53\n00:05:39.079 --> 00:05:43.091\n<i>禁止入内</i>\n\n54\n00:05:43.177 --> 00:05:44.303\n嘿\n\n55\n00:05:44.386 --> 00:05:45.721\n吉米\n\n56\n00:05:52.436 --> 00:05:55.230\n-伙计 你好吗\n-嘿\n\n57\n00:06:07.125 --> 00:06:09.929\n-爸爸\n-吉米\n\n58\n00:06:17.127 --> 00:06:20.547\n我刚才的比赛很精彩 13次三振出局\n\n59\n00:06:21.173 --> 00:06:22.633\n你赢了吗？\n\n60\n00:06:32.309 --> 00:06:36.021\n刚刚了解到我们可能又要搬家了\n\n61\n00:06:37.606 --> 00:06:40.359\n-多大概率？\n-去西得克萨斯州\n\n62\n00:06:40.442 --> 00:06:42.986\n海军想让我去那儿征兵\n\n63\n00:06:43.070 --> 00:06:44.613\n得克萨斯？\n\n64\n00:06:44.696 --> 00:06:46.490\n-什么时候？\n-三周内\n\n65\n00:06:48.575 --> 00:06:51.245\n但是 爸爸 我们还有半个赛季没打\n\n66\n00:06:51.328 --> 00:06:52.913\n我知道\n\n67\n00:06:52.996 --> 00:06:55.624\n也许我能住在约翰逊家\n\n68\n00:06:55.707 --> 00:06:57.209\n我们是一家人 要一起搬\n\n69\n00:07:05.425 --> 00:07:07.761\n我没有选择\n\n70\n00:07:13.183 --> 00:07:15.644\n他们打哪种棒球？\n\n71\n00:07:16.228 --> 00:07:17.729\n他们不打棒球\n\n72\n00:07:20.357 --> 00:07:23.443\n我听说他们可能要开几场夏季舞会\n\n73\n00:07:24.903 --> 00:07:26.154\n好吧\n\n74\n00:07:52.264 --> 00:07:53.599\n那些是什么？\n\n75\n00:07:53.682 --> 00:07:56.393\n-什么？\n-那些上下摆动的东西\n\n76\n00:07:57.060 --> 00:07:58.478\n石油钻塔\n\n77\n00:07:58.562 --> 00:08:02.524\n那些钻塔动起来的时候\n就表示是挖到油的好时机\n\n78\n00:08:03.358 --> 00:08:05.402\n看起来现在是好时机\n\n79\n00:08:48.904 --> 00:08:51.198\n糟了\n\n80\n00:08:51.281 --> 00:08:53.534\n我们一定把一些东西落在佛罗里达了\n\n81\n00:08:53.617 --> 00:08:56.245\n-落了什么？\n-我打包了几个箱子\n\n82\n00:08:56.328 --> 00:08:58.901\n里面有袜子和别的东西 我发誓…\n\n83\n00:08:58.901 --> 00:09:03.056\n吉米 你找到那个箱子了吗 噢 不\n\n84\n00:09:04.086 --> 00:09:07.381\n-没事 妈妈\n-不要担心 亲爱的 我们会找到的\n\n85\n00:09:09.591 --> 00:09:12.261\n我从没见过哪个男孩\n丢了袜子会这么难过\n\n86\n00:09:12.344 --> 00:09:13.971\n他的手套在里面\n\n87\n00:09:14.054 --> 00:09:16.890\n-他的什么？\n-他的手套\n\n88\n00:09:19.601 --> 00:09:21.854\n别郁闷了 快搬箱子\n\n89\n00:09:22.396 --> 00:09:24.481\n你听见了吗？\n\n90\n00:09:27.067 --> 00:09:29.486\n生命中比棒球重要的东西有很多\n\n91\n00:09:29.570 --> 00:09:32.447\n你越早明白越好\n\n92\n00:10:03.312 --> 00:10:06.607\n这个叫李·里瓦科·科屈斯的家伙\n\n93\n00:10:06.690 --> 00:10:09.985\n我向你们保证 两年之内 最多三年\n\n94\n00:10:10.068 --> 00:10:13.197\n他就会把那个公司搞破产\n\n95\n00:10:13.280 --> 00:10:15.490\n对不对 年轻人？\n\n96\n00:10:18.410 --> 00:10:20.037\n艾琳？\n\n97\n00:10:20.370 --> 00:10:21.872\n艾琳！\n\n98\n00:10:23.874 --> 00:10:26.168\n我想她是吃饭去了\n\n99\n00:10:30.589 --> 00:10:32.799\n能帮你找什么 孩子？\n\n100\n00:10:33.091 --> 00:10:35.260\n-袜子\n-我们有袜子\n\n101\n00:10:35.344 --> 00:10:37.012\n人们总觉得袜子很多\n\n102\n00:10:37.095 --> 00:10:39.765\n但现在似乎有点不够了\n\n103\n00:10:39.848 --> 00:10:43.101\n我这就下来 别看我的牌\n\n104\n00:10:45.354 --> 00:10:46.522\n我们这儿有白袜子\n\n105\n00:10:46.605 --> 00:10:48.941\n带红条纹 黑条纹 蓝条纹的\n\n106\n00:10:49.024 --> 00:10:52.653\n那边有带各种形状的\n黑的 蓝的 棕的 还有灰的\n\n107\n00:10:52.736 --> 00:10:54.613\n随你挑\n\n108\n00:10:54.696 --> 00:10:57.282\n那双真漂亮\n\n109\n00:10:58.033 --> 00:10:59.660\n你是来这里拜访谁的吗？\n\n110\n00:10:59.743 --> 00:11:03.580\n-我们刚搬到这里\n-这样啊 我是亨利·桑普森\n\n111\n00:11:03.664 --> 00:11:05.916\n很高兴认识你 吉米·莫里斯\n\n112\n00:11:05.999 --> 00:11:08.502\n欢迎来到比格莱克\n吉米·莫里斯先生\n\n113\n00:11:29.481 --> 00:11:31.149\n孩子 我可以告诉你在哪儿\n\n114\n00:11:31.233 --> 00:11:33.735\n比你自己找要快多了\n\n115\n00:11:39.199 --> 00:11:42.494\n-有棒球装备吗？\n-棒球装备\n\n116\n00:11:43.537 --> 00:11:46.665\n我们这儿没多少人需要棒球装备\n\n117\n00:11:46.748 --> 00:11:50.127\n如果是足球 那就不一样了\n\n118\n00:11:54.590 --> 00:11:56.550\n但是你知道吗 我这儿有个目录\n\n119\n00:11:56.633 --> 00:12:00.429\n也许能帮我们搞到一些 咱们看看\n\n120\n00:12:06.185 --> 00:12:09.188\n也许我们能从这儿找到一些\n\n121\n00:12:09.813 --> 00:12:12.357\n如果你对棒球感兴趣\n\n122\n00:12:12.441 --> 00:12:14.735\n也许你应该听听\n\n123\n00:12:14.818 --> 00:12:16.862\n这里的人们讲的一个故事\n\n124\n00:12:16.945 --> 00:12:20.324\n你不是说这儿的人不关心棒球吗？\n\n125\n00:12:20.616 --> 00:12:22.618\n他们关心\n\n126\n00:12:23.702 --> 00:12:26.413\n故事要从两个修女说起\n\n127\n00:12:27.581 --> 00:12:30.417\n就发生在离这儿不远的地方\n\n128\n00:13:23.113 --> 00:13:25.159\n<i>比格莱克油田发源地</i>\n<i>圣丽塔1号 1923年5月27日</i>\n\n129\n00:14:04.532 --> 00:14:07.997\n<i>圣丽塔为我们祈祷</i>\n\n130\n00:15:03.278 --> 00:15:05.239\n-早 埃丝特\n-早 吉米\n\n131\n00:15:05.322 --> 00:15:06.782\n操场上还有响尾蛇吗？\n\n132\n00:15:06.865 --> 00:15:09.701\n是的 今天早上有两条\n我发誓 每次石油生意不好的时候\n\n133\n00:15:09.785 --> 00:15:11.411\n它们就会出现\n\n134\n00:15:11.495 --> 00:15:14.206\n-他们要让孩子们进去吗？\n-他们还在考虑\n\n135\n00:15:14.289 --> 00:15:17.376\n难道这些家庭要担心的还不够多吗？\n\n136\n00:15:17.709 --> 00:15:19.419\n-教练\n-辅导员\n\n137\n00:15:24.341 --> 00:15:26.760\n-别汇报这个 埃丝特\n-我从不会\n\n138\n00:15:29.513 --> 00:15:33.267\n求和意味着相加 我们至少得有两项\n\n139\n00:15:34.852 --> 00:15:37.688\n别想得太难 但我们要加上什么呢？\n\n140\n00:15:37.771 --> 00:15:39.731\n-质子和…\n-中子？\n\n141\n00:15:39.815 --> 00:15:42.693\n中子 中子\n\n142\n00:15:42.985 --> 00:15:46.822\n戴维 这些质子和中子\n\n143\n00:15:46.905 --> 00:15:49.241\n它们在什么里面？\n\n144\n00:15:51.410 --> 00:15:53.745\n-原子核？\n-别像在提问 孩子\n\n145\n00:15:53.829 --> 00:15:57.082\n如果你觉得你知道答案\n就确定地说出来\n\n146\n00:15:57.165 --> 00:15:59.793\n-原子核\n-对 原子核\n\n147\n00:16:00.669 --> 00:16:03.088\n恭喜各位 今晚回家告诉你们的父母\n\n148\n00:16:03.172 --> 00:16:05.716\n你们学习了原子质量数\n\n149\n00:16:08.093 --> 00:16:10.637\n弗兰克 现在放这首歌\n是不是有些晚了？\n\n150\n00:16:10.721 --> 00:16:12.347\n-现在是八点半\n-现在是三月\n\n151\n00:16:13.432 --> 00:16:15.552\n这首歌太好听了 不能只放一个月\n\n152\n00:16:15.552 --> 00:16:17.302\n亨特 你想要奶酪吗？\n\n153\n00:16:17.394 --> 00:16:18.854\n-是的\n-还有\n\n154\n00:16:18.937 --> 00:16:21.315\n-他一天抽三包烟\n-谁？\n\n155\n00:16:21.398 --> 00:16:23.859\n纳京高\n他觉得这会让他的声音更低沉\n\n156\n00:16:23.942 --> 00:16:27.029\n弗兰克·西纳特拉\n是保养嗓音的典型代表吗？\n\n157\n00:16:27.112 --> 00:16:29.907\n谁40多岁就死了？你照顾好自己吧\n\n158\n00:16:29.990 --> 00:16:32.701\n-起作用了\n-对吧？\n\n159\n00:16:32.784 --> 00:16:36.008\n吉米怎么样？他把自己照顾得很好\n\n160\n00:16:36.008 --> 00:16:38.795\n几次手术 吉米 四次吗？\n\n161\n00:16:38.874 --> 00:16:42.294\n从脚踝到肩膀都开了刀\n\n162\n00:16:43.337 --> 00:16:45.839\n我们在讨论唱歌 不是投球\n\n163\n00:16:45.923 --> 00:16:49.510\n亨特 帮我们个忙 以后别再提\n\n164\n00:16:49.593 --> 00:16:52.179\n-脚踝的事情了\n-六月的梅尔·托尔梅\n\n165\n00:16:52.262 --> 00:16:53.639\n你现在究竟在说些什么？\n\n166\n00:16:53.722 --> 00:16:57.351\n梅尔·托尔梅在某个海滩\n写出了《圣诞歌》\n\n167\n00:16:57.434 --> 00:17:01.313\n那天的严寒可没冻伤谁的鼻子\n\n168\n00:17:05.150 --> 00:17:06.568\n-爸爸？\n-怎么了\n\n169\n00:17:06.652 --> 00:17:08.819\n你的胳膊还疼吗？\n\n170\n00:17:09.613 --> 00:17:10.948\n只有早上不得不把你拖下床\n去上学的时候才疼\n\n171\n00:17:13.992 --> 00:17:16.578\n我在逗你呢 已经很久不疼了\n\n172\n00:17:16.662 --> 00:17:17.996\n多久了？\n\n173\n00:17:20.582 --> 00:17:23.794\n-为什么问？\n-只是好奇\n\n174\n00:17:26.547 --> 00:17:28.382\n我想想\n\n175\n00:17:29.341 --> 00:17:33.971\n我上高中的时候从没疼过\n因为我们没有棒球队\n\n176\n00:17:34.054 --> 00:17:36.765\n我上大专的时候从没疼过\n\n177\n00:17:36.849 --> 00:17:39.142\n所以我就去参加选拔了\n\n178\n00:17:39.476 --> 00:17:43.188\n之后 我也不知道怎么回事\n它就开始疼了\n\n179\n00:17:46.275 --> 00:17:48.694\n这就是你没成功的原因吗？\n\n180\n00:17:53.115 --> 00:17:54.950\n这是两回事\n\n181\n00:18:52.257 --> 00:18:54.384\n我去看看\n\n182\n00:18:54.468 --> 00:18:56.887\n是真的“我去看看”\n\n183\n00:18:56.970 --> 00:19:00.140\n还是只是等着我说 “你睡吧”？\n\n184\n00:19:00.224 --> 00:19:02.100\n我还没想好\n\n185\n00:19:03.352 --> 00:19:05.103\n你睡吧\n\n186\n00:19:14.613 --> 00:19:16.740\n你在哭什么呢？\n\n187\n00:19:18.825 --> 00:19:20.786\n我想轮到我了\n\n188\n00:19:20.869 --> 00:19:23.539\n不 轮到你睡觉了\n\n189\n00:19:25.249 --> 00:19:26.625\n好吧\n\n190\n00:19:28.043 --> 00:19:30.671\n-你确定？\n-是啊\n\n191\n00:19:32.714 --> 00:19:34.967\n好啦 宝贝\n\n192\n00:19:35.050 --> 00:19:36.510\n有我们呢\n\n193\n00:19:37.052 --> 00:19:39.680\n-晚安\n-晚安\n\n194\n00:19:43.225 --> 00:19:44.726\n好了\n\n195\n00:20:14.089 --> 00:20:16.967\n鲁迪 你上次约会是什么时候？\n\n196\n00:20:17.384 --> 00:20:18.760\n大概一年前吧\n\n197\n00:20:18.844 --> 00:20:20.846\n-够了 哥们儿\n-来吧 哥们儿\n\n198\n00:20:20.929 --> 00:20:23.974\n你在开玩笑吧？你也是 鲁迪 别笑\n\n199\n00:20:24.057 --> 00:20:25.517\n-都准备好了 教练\n-你不是唯一一个\n\n200\n00:20:25.601 --> 00:20:27.144\n给我个球\n\n201\n00:20:29.104 --> 00:20:33.483\n-教练 我忘了拿手套\n-看看包里有没有\n\n202\n00:20:33.567 --> 00:20:35.777\n-十个球员 九双手套\n-是啊\n\n203\n00:20:35.861 --> 00:20:38.238\n-它们看上去怎么样？\n-有几个洞\n\n204\n00:20:38.322 --> 00:20:40.657\n-好吧 拿一个吧\n-谢啦 伙计\n\n205\n00:20:43.118 --> 00:20:46.455\n教练\n他们今年在球场上铺草籽了吗？\n\n206\n00:20:46.538 --> 00:20:49.208\n那边有山羊的脚印\n\n207\n00:20:49.291 --> 00:20:53.128\n-在等着吃草籽吧\n-什么草籽？\n\n208\n00:20:54.213 --> 00:20:56.798\n-这儿没有草籽\n-瓦克！\n\n209\n00:20:58.634 --> 00:21:00.511\n为什么我们这么脏\n足球场却干净得像\n\n210\n00:21:00.594 --> 00:21:03.722\n-泰格·伍兹的后院呢？\n-他们甚至六个月没踢了\n\n211\n00:21:03.805 --> 00:21:06.433\n就让我来操心球场的事吧 好吗\n\n212\n00:21:06.517 --> 00:21:09.811\n-你打算马上就要开始操心了吗？\n-好吧 瓦克\n\n213\n00:21:09.895 --> 00:21:12.564\n你今天可以早点跑完\n\n214\n00:21:12.648 --> 00:21:16.735\n-好吧 我早点跑\n-看起来不错\n\n215\n00:21:18.153 --> 00:21:20.155\n把球带回家！\n\n216\n00:21:27.204 --> 00:21:29.373\n教练 你想投球吗？\n\n217\n00:21:30.791 --> 00:21:34.127\n我之前在晚上的旧军队球场上\n看见过你\n\n218\n00:21:34.211 --> 00:21:36.004\n你投球的时候要是有人接球\n会很不错的\n\n219\n00:21:36.088 --> 00:21:41.134\n棒球 手套 之类的东西\n\n220\n00:21:44.054 --> 00:21:46.348\n-我来投几个\n-真的吗？\n\n221\n00:21:48.600 --> 00:21:49.643\n好吧\n\n222\n00:21:55.774 --> 00:21:58.610\n你怎么投 全靠你自己吗？\n\n223\n00:21:58.694 --> 00:22:00.112\n帮我放松\n\n224\n00:22:00.195 --> 00:22:01.864\n我一直在投球\n\n225\n00:22:02.739 --> 00:22:04.533\n很长时间了\n\n226\n00:22:10.038 --> 00:22:12.291\n教练\n以前你以投球为职业的时候\n\n227\n00:22:12.374 --> 00:22:17.045\n-你能投多快？\n-不知道 137 138吧\n\n228\n00:22:17.129 --> 00:22:17.963\n真不错\n\n229\n00:22:18.046 --> 00:22:22.301\n那时候其他人能达到145\n\n230\n00:22:23.760 --> 00:22:26.471\n教练 来啊 投一个\n\n231\n00:22:26.555 --> 00:22:28.307\n不行\n\n232\n00:22:28.390 --> 00:22:30.100\n我答应过很多医生\n\n233\n00:22:30.184 --> 00:22:32.978\n来吧 教练 投一个不会要了你的命的\n\n234\n00:22:35.147 --> 00:22:39.234\n-就现在 来吧 给我投一个\n-是啊 爸爸 给点儿力\n\n235\n00:22:43.572 --> 00:22:45.282\n投一个给我 教练\n\n236\n00:22:54.333 --> 00:22:56.001\n教练\n\n237\n00:22:57.669 --> 00:23:01.840\n-那是从哪儿来的？\n-差点忘了投球的声音有多美妙\n\n238\n00:23:04.885 --> 00:23:06.720\n真棒\n\n239\n00:23:42.548 --> 00:23:44.091\n真不可思议\n\n240\n00:23:46.802 --> 00:23:49.930\n教练 你认为球速有多快？\n\n241\n00:23:50.013 --> 00:23:52.182\n没你想得那么快\n\n242\n00:23:52.516 --> 00:23:54.434\n帮我个忙 好吗？\n\n243\n00:23:54.518 --> 00:23:56.395\n这是咱俩之间的秘密\n\n244\n00:23:56.478 --> 00:23:59.731\n-好吧\n-最后那一下很少见\n\n245\n00:23:59.815 --> 00:24:02.317\n你也是 好吗？别告诉妈妈\n\n246\n00:24:02.401 --> 00:24:03.777\n为什么？\n\n247\n00:24:05.487 --> 00:24:06.989\n因为我让你不要说\n\n248\n00:24:18.542 --> 00:24:20.294\n晚安 雷\n\n249\n00:24:20.377 --> 00:24:22.921\n我知道为什么你的草不长了\n\n250\n00:24:34.933 --> 00:24:37.936\n通常每天晚上都有三四只\n\n251\n00:24:38.020 --> 00:24:40.772\n我把草籽铺下 它们就吃掉\n\n252\n00:24:41.565 --> 00:24:44.526\n一旦草长高 它们就没那么喜欢了\n\n253\n00:24:45.027 --> 00:24:47.696\n这就是为什么足球场看起来状况良好\n\n254\n00:24:47.779 --> 00:24:49.489\n是吗？\n\n255\n00:24:49.573 --> 00:24:51.700\n也许那些踢足球的\n\n256\n00:24:51.783 --> 00:24:54.494\n用他们的大把经费来贿赂这些鹿了\n\n257\n00:24:58.665 --> 00:25:01.585\n嘿！走开！离开这儿！\n\n258\n00:25:08.467 --> 00:25:11.386\n我以为鹿很容易受惊\n\n259\n00:25:16.433 --> 00:25:18.435\n你想让我倒满吗？\n\n260\n00:25:19.853 --> 00:25:22.189\n没什么比用雪佛龙信用卡买的酒\n更美味的了\n\n261\n00:25:22.272 --> 00:25:24.858\n我知道你是个要求很高的消费者\n\n262\n00:25:25.567 --> 00:25:27.486\n-是吗？\n-是啊\n\n263\n00:25:38.413 --> 00:25:39.957\n我今天投球了\n\n264\n00:25:41.750 --> 00:25:43.794\n投给乔尔 练习之后投的\n\n265\n00:25:45.212 --> 00:25:47.005\n-你投球了？\n-对\n\n266\n00:25:48.298 --> 00:25:49.591\n用了多大力气？\n\n267\n00:25:51.051 --> 00:25:52.427\n很用力\n\n268\n00:26:01.979 --> 00:26:05.023\n不要担心 如果感觉到疼 我会停下的\n\n269\n00:26:05.107 --> 00:26:06.900\n是吗？你发誓\n\n270\n00:26:09.319 --> 00:26:11.780\n我去看看孩子们\n\n271\n00:26:17.494 --> 00:26:20.205\n哥们儿 消音器换了\n\n272\n00:26:20.289 --> 00:26:23.750\n吉普车 五公里外都听不到我来了\n你能吗？\n\n273\n00:26:23.834 --> 00:26:27.212\n-雷 当心这个螺旋球\n-女孩儿们喜欢吉普车\n\n274\n00:26:27.796 --> 00:26:30.174\n来 兄弟 碰一下\n\n275\n00:26:33.594 --> 00:26:36.096\n好 来几次击球练习\n\n276\n00:26:36.180 --> 00:26:38.098\n不行 鲁迪不在\n\n277\n00:26:38.182 --> 00:26:39.808\n-他在哪儿？\n-更衣室\n\n278\n00:26:39.892 --> 00:26:42.686\n好像是他只有一只鞋\n\n279\n00:26:46.148 --> 00:26:49.860\n-拿个球棒过来\n-你要在击球练习中投球吗？\n\n280\n00:26:49.943 --> 00:26:51.403\n对\n\n281\n00:26:51.486 --> 00:26:52.943\n-我第一个来 伙计\n-我第二\n\n282\n00:26:52.943 --> 00:26:55.344\n-好吧\n-我中大奖了！\n\n283\n00:26:57.701 --> 00:27:00.454\n来啊 伙计 投啊 投啊！\n\n284\n00:27:00.537 --> 00:27:02.414\n你怎么说，瓦克？\n\n285\n00:27:08.837 --> 00:27:10.297\n好啊\n\n286\n00:27:10.380 --> 00:27:13.050\n看起来那个球要落到其他时区了\n教练！\n\n287\n00:27:13.133 --> 00:27:15.969\n开始投下一个球值钱\n你最好把表调一下\n\n288\n00:27:16.053 --> 00:27:17.554\n你看到了吗？\n\n289\n00:27:18.305 --> 00:27:19.723\n看到了\n\n290\n00:27:22.518 --> 00:27:23.810\n来\n\n291\n00:27:27.856 --> 00:27:29.191\n耶\n\n292\n00:27:41.370 --> 00:27:42.871\n那是什么？\n\n293\n00:27:43.622 --> 00:27:44.706\n天啊！\n\n294\n00:27:45.249 --> 00:27:47.000\n等他热好身\n\n295\n00:27:50.879 --> 00:27:52.840\n-让我再看一次\n-不\n\n296\n00:27:52.923 --> 00:27:55.884\n这是击球练习 不是投球练习\n\n297\n00:27:57.094 --> 00:27:58.387\n好吧\n\n298\n00:27:59.137 --> 00:28:01.139\n我的天！\n\n299\n00:28:02.182 --> 00:28:04.309\n我已经输了25美分了\n\n300\n00:28:05.394 --> 00:28:09.147\n你打算投多少工作申请 吉米？\n\n301\n00:28:09.231 --> 00:28:11.733\n尽可能多吧 我想\n\n302\n00:28:11.817 --> 00:28:14.570\n那个到我店里来买袜子\n\n303\n00:28:14.653 --> 00:28:18.991\n搬了很多次家的小男孩儿\n现在要有自己的打算了？\n\n304\n00:28:19.074 --> 00:28:22.536\n-这不一样\n-总是这样\n\n305\n00:28:22.619 --> 00:28:25.497\n我听说你诊断出毛病\n不能上棒球场了\n\n306\n00:28:25.581 --> 00:28:29.209\n-你是说他很有潜力的那个球场\n-诊断的时候还好\n\n307\n00:28:29.293 --> 00:28:30.669\n治疗是个大麻烦\n\n308\n00:28:30.752 --> 00:28:32.629\n-我拿五个\n-几年前我也有同样的问题\n\n309\n00:28:32.713 --> 00:28:35.465\n-就在我家\n-是吗？\n\n310\n00:28:36.592 --> 00:28:39.344\n-你怎么了？\n-也给我五个\n\n311\n00:28:39.970 --> 00:28:41.972\n让我问问你 接下来几周\n\n312\n00:28:42.055 --> 00:28:46.602\n-你们要在那个球场上打几场比赛？\n-我们下周五打一场\n\n313\n00:28:46.685 --> 00:28:49.021\n之后直到月底才打\n\n314\n00:28:49.104 --> 00:28:51.440\n你觉得你能让你的孩子们\n那么久不上场吗？\n\n315\n00:28:51.523 --> 00:28:54.651\n我说的是不练习 什么也不做\n\n316\n00:28:56.111 --> 00:28:58.614\n亨利 为什么我有种感觉\n\n317\n00:28:58.697 --> 00:29:00.282\n我根本不想知道这些？\n\n318\n00:29:00.365 --> 00:29:02.067\n我会带上两个老家伙\n\n319\n00:29:02.067 --> 00:29:04.493\n-如果大家愿意的话\n-我告诉你你做什么\n\n320\n00:29:04.578 --> 00:29:08.707\n你给我三周时间\n我会让那个球场看起来\n\n321\n00:29:08.790 --> 00:29:10.876\n比圣帕特里克节那天的都柏林还要绿\n\n322\n00:29:10.959 --> 00:29:13.003\n五十美分 伙计们\n\n323\n00:29:15.172 --> 00:29:17.341\n好啦 来个安打 来啊\n\n324\n00:29:17.424 --> 00:29:20.219\n鲁迪·博尼拉想要\n让比格莱克为之振奋\n\n325\n00:29:20.302 --> 00:29:22.429\n来啊 鲁迪 当击球手！\n\n326\n00:29:23.222 --> 00:29:25.015\n保持注意力\n\n327\n00:29:27.851 --> 00:29:29.186\n三振出局！\n\n328\n00:29:29.269 --> 00:29:32.981\n三振出局\n猫头鹰队退出了他们的揭幕赛\n\n329\n00:29:34.191 --> 00:29:35.692\n没事的\n\n330\n00:29:35.776 --> 00:29:38.111\n没关系 你们尽力了 只有这一次\n\n331\n00:29:38.195 --> 00:29:40.906\n如果我们击不中球\n就不会只有这一次\n\n332\n00:29:40.989 --> 00:29:42.115\n打得好 伙计们\n\n333\n00:29:42.199 --> 00:29:45.160\n各位 现在回家吧 路上小心\n\n334\n00:29:51.208 --> 00:29:55.003\n-你的扫帚放在哪儿 卡尔？\n-在壁橱里\n\n335\n00:30:16.316 --> 00:30:18.443\n往这儿投 亲爱的\n\n336\n00:30:18.527 --> 00:30:20.737\n科里 保持 就这么保持\n\n337\n00:30:29.493 --> 00:30:31.626\n-上二垒 米格尔！\n-二垒！\n\n338\n00:30:38.881 --> 00:30:40.674\n-暂停！\n-中场！\n\n339\n00:30:43.177 --> 00:30:45.721\n猫头鹰队落后十分\n\n340\n00:30:48.098 --> 00:30:51.268\n-你只不过今天不在状态 鲁迪\n-今年都不在状态\n\n341\n00:30:54.229 --> 00:30:59.151\n看起来吉米·莫里斯教练换了投手\n\n342\n00:31:01.737 --> 00:31:03.447\n振作点 鲁迪\n\n343\n00:31:07.284 --> 00:31:11.288\n提醒各位 小卖部仍在营业\n\n344\n00:31:17.961 --> 00:31:20.964\n有人想告诉我\n我们是怎么输了这场比赛的吗?\n\n345\n00:31:24.301 --> 00:31:25.427\n没人吗？\n\n346\n00:31:26.803 --> 00:31:31.058\n看看计分板上的分数\n\n347\n00:31:31.683 --> 00:31:33.936\n那些数字代表什么？\n\n348\n00:31:34.686 --> 00:31:37.147\n怎么联系博的轮胎仓\n\n349\n00:31:42.778 --> 00:31:43.946\n你放弃了\n\n350\n00:31:46.365 --> 00:31:48.242\n你比赛时放弃了\n\n351\n00:31:49.159 --> 00:31:52.412\n你们放弃了我\n更糟的是 你们放弃了你们自己\n\n352\n00:31:53.205 --> 00:31:54.122\n现在是什么情况？\n\n353\n00:31:54.206 --> 00:31:56.959\n你们觉得这里的人不在乎棒球是吗？\n\n354\n00:31:57.042 --> 00:31:59.920\n觉得学校会放弃这个项目？\n\n355\n00:32:00.546 --> 00:32:03.090\n你们只是让他们更容易放弃了\n\n356\n00:32:03.173 --> 00:32:05.968\n悲哀的是 我看出来了 而你们并没有\n\n357\n00:32:09.888 --> 00:32:11.932\n孩子们\n\n358\n00:32:12.015 --> 00:32:13.851\n你们之中大多数\n\n359\n00:32:14.935 --> 00:32:17.229\n要在这里完成学业 要去操作钻塔\n\n360\n00:32:17.312 --> 00:32:20.440\n你们会在博的轮胎仓工作\n你们要养家 退休\n\n361\n00:32:20.524 --> 00:32:23.819\n这一切都要在比格莱克进行\n\n362\n00:32:24.111 --> 00:32:26.488\n这没有什么错\n\n363\n00:32:26.572 --> 00:32:29.324\n许许多多非常棒的人都是这么过来的\n\n364\n00:32:29.616 --> 00:32:31.034\n我也如此\n\n365\n00:32:32.286 --> 00:32:35.539\n但如果你在这儿完成学业后\n还有别的追求\n\n366\n00:32:36.665 --> 00:32:40.127\n你们最好认真想想要怎么打完\n\n367\n00:32:40.210 --> 00:32:43.338\n-这个赛季\n-有什么区别呢？\n\n368\n00:32:43.422 --> 00:32:47.217\n我们又拿不到奖学金\n\n369\n00:32:47.843 --> 00:32:50.596\n我说的不是大学\n\n370\n00:32:50.679 --> 00:32:53.473\n我说的是人生的追求\n\n371\n00:32:54.683 --> 00:32:56.935\n我说的是梦想\n\n372\n00:32:58.562 --> 00:33:01.648\n还有一切从这里发源的事\n\n373\n00:33:01.732 --> 00:33:03.400\n好吗？就从这里\n\n374\n00:33:04.318 --> 00:33:07.029\n你们没有梦想 你们什么都没有\n\n375\n00:33:07.112 --> 00:33:09.489\n教练 你呢？\n\n376\n00:33:09.573 --> 00:33:11.992\n你一直说我们的梦想\n\n377\n00:33:13.952 --> 00:33:16.163\n-我意思是，我已经接球...\n-乔尔 我们讨论的不是我\n\n378\n00:33:16.246 --> 00:33:18.415\n说说吧 教练\n\n379\n00:33:18.498 --> 00:33:21.960\n每次你投球\n我的手都无法动弹 每次都是\n\n380\n00:33:24.046 --> 00:33:26.840\n你才是那个应该追求更多的人\n\n381\n00:33:26.924 --> 00:33:29.384\n悲哀的是\n\n382\n00:33:29.468 --> 00:33:31.470\n我们看出来了 你却没有\n\n383\n00:33:32.804 --> 00:33:35.766\n我已经试过了 好吧？ 只不过...\n\n384\n00:33:36.433 --> 00:33:39.186\n我们明天有训练\n\n385\n00:33:40.646 --> 00:33:43.273\n-咱们走吧\n-你再试试\n\n386\n00:33:43.357 --> 00:33:45.734\n-不是那样的\n-如果你用力投球就行\n\n387\n00:33:45.817 --> 00:33:48.529\n我不会用力投球 好吧？\n\n388\n00:33:49.196 --> 00:33:50.781\n我们去冲澡吧 来吧\n\n389\n00:33:50.864 --> 00:33:54.409\n等等 我们开始赢的话 你就再试试\n\n390\n00:33:59.540 --> 00:34:02.000\n上次我查过 球探不会找上\n高中科学老师的\n\n391\n00:34:03.752 --> 00:34:06.922\n像你一样会投球的科学老师可不多\n\n392\n00:34:07.005 --> 00:34:08.047\n-是啊\n-没有开玩笑\n\n393\n00:34:08.130 --> 00:34:09.757\n-对\n-没说谎\n\n394\n00:34:11.426 --> 00:34:14.054\n可不是几场胜利\n\n395\n00:34:14.137 --> 00:34:17.724\n-就能让我出洋相\n-好吧\n\n396\n00:34:17.808 --> 00:34:19.768\n要是我们能在区里获胜呢？\n\n397\n00:34:20.893 --> 00:34:24.313\n要是我们在区里获胜\n打入州级赛呢？\n\n398\n00:34:27.609 --> 00:34:29.820\n-你们是认真的吗？\n-是啊 当然\n\n399\n00:34:31.446 --> 00:34:33.614\n-你们是认真的？\n-对\n\n400\n00:34:34.116 --> 00:34:35.324\n是啊\n\n401\n00:34:37.911 --> 00:34:40.914\n而我要做的只是参加几场选拔赛？\n\n402\n00:34:40.998 --> 00:34:42.331\n就是这样\n\n403\n00:34:44.458 --> 00:34:46.460\n好\n\n404\n00:34:46.545 --> 00:34:49.297\n-如果你们在区里获胜的话\n-耶\n\n405\n00:34:49.380 --> 00:34:51.632\n-来吧 兄弟们 我们能行！\n-你说得对\n\n406\n00:34:51.925 --> 00:34:53.552\n教练！\n\n407\n00:34:55.179 --> 00:34:56.804\n我们能行！\n\n408\n00:34:59.892 --> 00:35:02.936\n我不能告诉妈妈 对吗？\n\n409\n00:35:11.406 --> 00:35:15.452\n<i>里特斯汽油</i>\n\n410\n00:35:55.459 --> 00:35:57.879\n<i>你的速度31</i>\n\n411\n00:37:45.760 --> 00:37:47.096\n<i>限速35</i>\n\n412\n00:38:12.042 --> 00:38:13.669\n你确定吗 亨利？\n\n413\n00:38:13.752 --> 00:38:17.548\n是啊 鹿要是闻到人类头发的\n一丝气味 它们就会一直走开\n\n414\n00:38:17.631 --> 00:38:19.967\n直到闻不到为止\n\n415\n00:38:20.050 --> 00:38:24.888\n我想我们应该在这里绕一圈\n\n416\n00:38:25.180 --> 00:38:27.099\n头发很多啊\n\n417\n00:38:27.850 --> 00:38:31.895\n从表面上看 和大家的看法相反\n\n418\n00:38:31.979 --> 00:38:35.399\n卡尔没在他的店欺骗过任何人\n\n419\n00:38:40.654 --> 00:38:44.491\n最好戴上护目镜 马丁内斯女士\n\n420\n00:38:44.640 --> 00:38:45.720\n教练\n\n421\n00:38:50.205 --> 00:38:52.875\n是我想的那样吗？\n\n422\n00:38:55.711 --> 00:38:58.714\n那是百慕大杂交五号\n\n423\n00:38:58.922 --> 00:39:01.300\n我们要有棒球场了\n\n424\n00:39:05.470 --> 00:39:09.725\n-可能他不在家\n-但他说他在的\n\n425\n00:39:13.488 --> 00:39:15.400\n-嗨 爷爷\n-亨特\n\n426\n00:39:16.064 --> 00:39:20.194\n我今早在报纸上看到\n\n427\n00:39:20.277 --> 00:39:23.739\n-你家有人过生日\n-那是逗孩子的 爷爷\n\n428\n00:39:23.822 --> 00:39:26.491\n逗孩子的？不是开玩笑？\n\n429\n00:39:29.244 --> 00:39:30.746\n-吉米\n-长官\n\n430\n00:39:44.426 --> 00:39:46.053\n这只手套有点大\n\n431\n00:39:46.303 --> 00:39:49.348\n很快你就会长大 能用了\n这比你想象得快\n\n432\n00:39:49.640 --> 00:39:52.267\n看啊 爸爸 没有放手指的地方\n\n433\n00:39:53.018 --> 00:39:55.938\n这是因为它是一垒手的手套\n\n434\n00:39:57.773 --> 00:39:59.274\n买错了吗？\n\n435\n00:40:01.276 --> 00:40:04.488\n我可能把收据放在哪个地方了\n\n436\n00:40:05.113 --> 00:40:07.074\n我们可以 我们可以再买一个\n\n437\n00:40:07.157 --> 00:40:09.701\n-买一个带手指的\n-没关系 爷爷\n\n438\n00:40:09.785 --> 00:40:11.411\n我喜欢一垒\n\n439\n00:40:14.665 --> 00:40:17.209\n我能出去玩吗 爸爸？\n\n440\n00:40:17.626 --> 00:40:18.794\n去吧\n\n441\n00:40:19.545 --> 00:40:22.297\n-你得说什么？\n-谢谢爷爷\n\n442\n00:40:22.381 --> 00:40:24.800\n我非常喜欢\n\n443\n00:40:33.308 --> 00:40:35.018\n就在院子里玩\n\n444\n00:40:35.811 --> 00:40:38.063\n如果他觉得他想要一个带手指的…\n\n445\n00:40:38.146 --> 00:40:40.023\n我来搞定\n\n446\n00:40:54.830 --> 00:40:57.040\n我不知道你有这些\n\n447\n00:40:58.166 --> 00:40:59.501\n是啊\n\n448\n00:41:01.003 --> 00:41:03.338\n你妈妈给了我几个\n\n449\n00:41:04.173 --> 00:41:06.341\n她确实像是有这些的人\n\n450\n00:41:13.557 --> 00:41:16.727\n祝你生日快乐\n\n451\n00:41:17.728 --> 00:41:21.690\n祝你生日快乐\n\n452\n00:41:22.024 --> 00:41:26.904\n生日快乐 亲爱的亨特\n\n453\n00:41:27.321 --> 00:41:32.034\n祝你生日快乐\n\n454\n00:41:34.620 --> 00:41:36.455\n-杰茜卡！\n-不要担心 宝贝\n\n455\n00:41:36.538 --> 00:41:38.832\n你的愿望仍然有效\n\n456\n00:41:38.916 --> 00:41:41.585\n查尔斯 你觉得冰淇淋机\n\n457\n00:41:41.668 --> 00:41:44.087\n会自己启动吗？\n\n458\n00:41:45.714 --> 00:41:46.920\n我去拿把刀\n\n459\n00:41:46.920 --> 00:41:50.494\n-我来帮你 妈妈\n-亲爱的 我觉得我们还需要盘子\n\n460\n00:41:57.309 --> 00:42:01.104\n好像五分钟前我还在看你吹蜡烛\n\n461\n00:42:01.188 --> 00:42:06.777\n-你想让我感觉自己老了吗？\n-20年后再和我说这个\n\n462\n00:42:09.238 --> 00:42:12.199\n亨特说你今天和你爸爸待了一会儿\n\n463\n00:42:12.282 --> 00:42:13.408\n是啊\n\n464\n00:42:14.409 --> 00:42:17.913\n-你知道我要说什么\n-是的 妈妈 我知道\n\n465\n00:42:19.164 --> 00:42:22.459\n罗莉说他在努力成为一个好爷爷\n\n466\n00:42:22.543 --> 00:42:24.795\n-是啊…\n-天啊 吉米 我发誓\n\n467\n00:42:24.878 --> 00:42:27.172\n你从他身上学到的是他固执的一面\n\n468\n00:42:27.256 --> 00:42:29.091\n不是的\n\n469\n00:42:31.260 --> 00:42:35.180\n你想让我做什么呢？\n假装一切都很完美吗？\n\n470\n00:42:35.264 --> 00:42:39.601\n多年来你一直在责怪你爸爸\n在很多事情上都责怪他\n\n471\n00:42:40.978 --> 00:42:43.146\n我看到什么就说什么 妈妈\n\n472\n00:42:43.230 --> 00:42:47.526\n吉米 你可以去别处说这些\n因为我不信\n\n473\n00:42:48.443 --> 00:42:50.612\n你之前去努力打棒球了\n\n474\n00:42:50.821 --> 00:42:53.824\n然后你受伤了 就是这样\n\n475\n00:42:53.907 --> 00:42:56.535\n和你爸爸一点关系都没有\n\n476\n00:42:57.494 --> 00:42:59.955\n你以为他没有梦想吗？\n\n477\n00:43:02.499 --> 00:43:05.252\n这就是为什么你俩的关系\n像现在这样吗？\n\n478\n00:43:05.752 --> 00:43:08.630\n要讨论这个的话\n我需要走一条更长的街\n\n479\n00:43:13.177 --> 00:43:15.220\n好 我们开始吧\n\n480\n00:43:16.263 --> 00:43:17.681\n来啊 瓦克！\n\n481\n00:43:18.015 --> 00:43:19.725\n教练 我们还要在这儿训练多久？\n\n482\n00:43:19.808 --> 00:43:23.061\n-还需要几天\n-我已经在这里变老了 教练\n\n483\n00:43:23.145 --> 00:43:24.980\n在满是碎石的院子里打球\n\n484\n00:43:25.063 --> 00:43:28.025\n好了 瓦克 来击球练习吧\n\n485\n00:43:29.735 --> 00:43:31.653\n这不是球场\n\n486\n00:43:32.362 --> 00:43:34.656\n-来吧 咱们开始吧\n-好吧 好吧\n\n487\n00:43:43.498 --> 00:43:44.666\n好\n\n488\n00:43:45.417 --> 00:43:49.338\n轻松摆动 扭一扭臀\n\n489\n00:43:49.421 --> 00:43:51.673\n朝着球伸手\n\n490\n00:43:53.563 --> 00:43:56.551\n教练 如果我们要开始赢的话\n\n491\n00:43:56.637 --> 00:43:58.889\n-我们得看看真正好的投球\n-是啊\n\n492\n00:43:58.972 --> 00:44:02.893\n-你要不要帮我们？\n-来吧 教练 这里\n\n493\n00:44:03.810 --> 00:44:05.896\n让我们看看你的动作\n\n494\n00:44:13.237 --> 00:44:14.821\n来吧 瓦克\n\n495\n00:45:01.451 --> 00:45:02.870\n兄弟！\n\n496\n00:45:04.298 --> 00:45:05.698\n好极了 兄弟\n\n497\n00:45:06.331 --> 00:45:08.208\n擦到边了！\n\n498\n00:45:08.292 --> 00:45:09.877\n现在\n\n499\n00:45:09.960 --> 00:45:12.129\n-完全击中了\n-你真厉害 瓦克\n\n500\n00:45:12.212 --> 00:45:13.714\n-是啊\n-加油 瓦克\n\n501\n00:45:14.381 --> 00:45:15.757\n加油 教练\n\n502\n00:45:21.305 --> 00:45:25.017\n冲 冲 冲 冲 冲！\n\n503\n00:45:25.706 --> 00:45:27.216\n阿塔韦 瓦克\n\n504\n00:45:28.770 --> 00:45:30.105\n快点！\n\n505\n00:45:33.442 --> 00:45:34.985\n跑啊 孩子 跑起来！\n\n506\n00:45:43.660 --> 00:45:45.204\n出局！\n\n507\n00:45:52.377 --> 00:45:53.670\n-接住它 乔尔！\n-接住它！\n\n508\n00:45:53.754 --> 00:45:56.215\n冲 冲 冲 冲 冲 冲！\n\n509\n00:45:57.883 --> 00:45:59.092\n耶！\n\n510\n00:46:10.479 --> 00:46:14.483\n击中它 伙计！看球啊 兄弟！\n\n511\n00:46:32.167 --> 00:46:34.962\n一直双杀感觉怎么样？\n\n512\n00:46:42.845 --> 00:46:47.099\n猫头鹰队又赢了 已经连赢五场了\n\n513\n00:46:49.582 --> 00:46:51.079\n<i>猫头鹰队连胜五场</i>\n\n514\n00:46:51.163 --> 00:46:52.701\n我们继续吧\n\n515\n00:46:57.192 --> 00:46:58.371\n跑啊 跑啊\n\n516\n00:46:58.371 --> 00:47:00.182\n<i>十二连胜 猫头鹰队一往无前！</i>\n\n517\n00:47:01.613 --> 00:47:03.198\n三振出局！\n\n518\n00:47:07.536 --> 00:47:09.413\n耶！\n\n519\n00:47:09.872 --> 00:47:13.125\n-耶 宝贝\n-快点 防御吧\n\n520\n00:47:16.170 --> 00:47:17.880\n他又接住了！\n\n521\n00:47:26.221 --> 00:47:28.090\n三振出局！\n\n522\n00:47:28.090 --> 00:47:30.242\n<i>天选之队！</i>\n<i>猫头鹰队为保持冠军而战</i>\n\n523\n00:47:35.564 --> 00:47:39.151\n跑啊 跑啊 跑到了！\n\n524\n00:47:46.033 --> 00:47:49.161\n猫头鹰队清垒了\n\n525\n00:47:56.168 --> 00:47:58.462\n-我们赢了！\n-耶！\n\n526\n00:48:06.720 --> 00:48:09.681\n嘿！嘿！嘿！现在安静点\n不然人们会认为\n\n527\n00:48:09.765 --> 00:48:13.769\n足球季已经开始了！\n\n528\n00:48:15.187 --> 00:48:18.899\n现在 许多教练都会说\n他们真的很为你们骄傲\n\n529\n00:48:18.982 --> 00:48:20.484\n-是啊\n-我也为你们骄傲\n\n530\n00:48:22.236 --> 00:48:24.863\n许多教练都会说\n\n531\n00:48:24.947 --> 00:48:29.618\n我们连续赢了这么多场比赛\n让人惊叹 确实是\n\n532\n00:48:31.565 --> 00:48:34.664\n但是 但是\n\n533\n00:48:34.748 --> 00:48:38.335\n我不会说我不在乎明天的比赛了\n\n534\n00:48:38.418 --> 00:48:40.295\n因为我很在乎\n\n535\n00:48:40.379 --> 00:48:42.714\n-那么让我们圆满完成这件事吧\n-耶！\n\n536\n00:48:43.689 --> 00:48:48.759\n州赛！州赛！州赛！州赛！州赛！\n\n537\n00:48:48.846 --> 00:48:51.014\n-你们队真棒\n-谢谢\n\n538\n00:48:51.098 --> 00:48:52.558\n我是史蒂夫·迪尔伯恩\n\n539\n00:48:52.641 --> 00:48:54.893\n我在沃思堡的巴顿学区工作\n\n540\n00:48:54.977 --> 00:48:59.055\n我想谈谈你寄给我们的工作申请\n\n541\n00:48:59.055 --> 00:48:59.896\n当然\n\n542\n00:49:07.294 --> 00:49:13.517\n<i>教练办公室</i>\n\n543\n00:49:16.081 --> 00:49:17.875\n他们会理解的\n\n544\n00:49:18.667 --> 00:49:20.419\n我让他们大多数人都回来了\n\n545\n00:49:20.502 --> 00:49:22.379\n吉米 你总会有回来的孩子的\n\n546\n00:49:22.462 --> 00:49:24.089\n但不是这些孩子了\n\n547\n00:49:24.173 --> 00:49:28.677\n那是沃思堡啊\n高中教练这份工作待遇只会这样了\n\n548\n00:49:30.012 --> 00:49:32.598\n你训练 教学\n\n549\n00:49:32.681 --> 00:49:34.752\n而这不是生命中最重要的事\n\n550\n00:49:34.752 --> 00:49:37.692\n但那是两倍的钱啊 吉米\n\n551\n00:49:38.604 --> 00:49:40.856\n-我们会需要这些钱的\n-我知道\n\n552\n00:49:43.901 --> 00:49:45.152\n好吧\n\n553\n00:49:46.028 --> 00:49:50.282\n我不会让你明天再想了\n因为肯定没用\n\n554\n00:50:01.418 --> 00:50:05.548\n<i>猫头鹰队准备参加地区冠军赛</i>\n\n555\n00:50:42.167 --> 00:50:43.752\n三年前\n\n556\n00:50:44.586 --> 00:50:48.882\n赛季结束时 我们只赢了一场\n\n557\n00:50:51.927 --> 00:50:53.846\n两年前\n\n558\n00:50:53.929 --> 00:50:55.138\n一场\n\n559\n00:50:55.889 --> 00:50:57.266\n去年\n\n560\n00:50:58.267 --> 00:50:59.643\n一场\n\n561\n00:51:01.812 --> 00:51:03.188\n到了今年\n\n562\n00:51:04.439 --> 00:51:06.525\n我们赢了16场比赛\n\n563\n00:51:10.696 --> 00:51:12.239\n先生们\n\n564\n00:51:15.158 --> 00:51:16.451\n我们需要赢第17场\n\n565\n00:51:20.289 --> 00:51:22.124\n有人有什么问题吗？\n\n566\n00:51:24.209 --> 00:51:25.460\n教练\n\n567\n00:51:27.588 --> 00:51:29.548\n明年你会回来吗？\n\n568\n00:51:31.967 --> 00:51:36.138\n伙计 为什么我们不先担心今年呢\n对吧？\n\n569\n00:51:40.142 --> 00:51:42.811\n好了 先生们 摘下帽子\n\n570\n00:51:47.316 --> 00:51:51.069\n主啊 我们谦卑地感谢你\n引领我们走过这个赛季\n\n571\n00:51:51.153 --> 00:51:52.988\n没有受过伤 并激励我们...\n\n572\n00:51:53.071 --> 00:51:56.033\n<i>依然迎风招展</i>\n\n573\n00:51:56.116 --> 00:52:00.871\n<i>火炮闪闪发光</i>\n\n574\n00:52:00.954 --> 00:52:05.167\n<i>炸弹轰轰作响</i>\n\n575\n00:52:05.250 --> 00:52:09.630\n<i>它们都是见证</i>\n\n576\n00:52:09.713 --> 00:52:14.426\n<i>国旗安然无恙</i>\n\n577\n00:52:14.510 --> 00:52:21.517\n<i>你看星条旗不是还高高飘扬</i>\n\n578\n00:52:26.355 --> 00:52:32.319\n<i>在这自由国家</i>\n\n579\n00:52:32.402 --> 00:52:39.368\n<i>勇士的家乡？</i>\n\n580\n00:52:41.954 --> 00:52:48.043\n来自比格莱克扶轮社长\n亨利·桑普森的激动人心的表演\n\n581\n00:53:00.806 --> 00:53:02.516\n好了 好了\n\n582\n00:53:02.599 --> 00:53:04.852\n跟上一次跟这些家伙比赛时不同\n我们已经今非昔比了\n\n583\n00:53:04.935 --> 00:53:09.565\n他们会被拿下的 我们别紧张就行\n\n584\n00:53:12.568 --> 00:53:15.070\n没什么可紧张的\n\n585\n00:53:19.032 --> 00:53:21.118\n我们来打棒球吧\n\n586\n00:53:31.545 --> 00:53:34.381\n-安全！\n-耶 耶\n\n587\n00:53:34.464 --> 00:53:37.342\n-来啊 伙计们\n-兄弟们 来啊 稳着点！\n\n588\n00:53:37.426 --> 00:53:39.052\n来啊 动起来 伙计！\n\n589\n00:53:39.136 --> 00:53:41.430\n-动起来！\n-给我球！\n\n590\n00:53:41.513 --> 00:53:43.348\n可恶！\n\n591\n00:53:43.432 --> 00:53:47.102\n比格莱克的孩子们处于劣势 二比零\n\n592\n00:53:47.186 --> 00:53:48.979\n抬着头 抬着头\n\n593\n00:53:49.062 --> 00:53:50.189\n-把比分追平\n-来吧 孩子们\n\n594\n00:53:50.272 --> 00:53:51.648\n-这是第一局\n-好吧 孩子们 没事\n\n595\n00:53:51.732 --> 00:53:56.195\n布兰登 拿球杆来\n乔·戴维 你做准备\n\n596\n00:53:56.278 --> 00:53:59.364\n这个家伙的球快得让人讨厌\n要小心他的曲线球 好吗？\n\n597\n00:53:59.448 --> 00:54:01.408\n-击球员就位！\n-好 一次击一个\n\n598\n00:54:01.491 --> 00:54:04.828\n-一次挥击一下 一次跑一个\n-来吧\n\n599\n00:54:04.912 --> 00:54:06.663\n来吧 你说什么 米格尔？\n\n600\n00:54:06.747 --> 00:54:08.290\n-好吧 米格尔 来\n-小心他\n\n601\n00:54:08.373 --> 00:54:10.292\n击中吧 击中吧\n\n602\n00:54:14.213 --> 00:54:15.797\n他出局了！\n\n603\n00:54:17.257 --> 00:54:19.760\n猫头鹰队依然是零分\n\n604\n00:54:23.472 --> 00:54:26.058\n-让他出局！\n-出局！\n\n605\n00:54:26.141 --> 00:54:29.478\n这大热天差点把\n我们孩子的头都融化了\n\n606\n00:54:38.779 --> 00:54:40.656\n滑啊 滑啊！\n\n607\n00:54:43.033 --> 00:54:45.827\n安全！比格莱克在得分位置了\n\n608\n00:54:45.911 --> 00:54:47.663\n你还好吗？\n\n609\n00:54:49.831 --> 00:54:52.501\n鲁迪·博尼拉要击球了\n\n610\n00:55:15.941 --> 00:55:17.442\n-安全！安全！\n-耶！\n\n611\n00:55:18.360 --> 00:55:21.655\n自杀式挤压 猫头鹰队首次得分\n\n612\n00:55:21.705 --> 00:55:24.759\n<i>猫头鹰荣誉</i>\n\n613\n00:55:33.250 --> 00:55:35.377\n来啊 球 跑啊！\n\n614\n00:55:38.881 --> 00:55:40.757\n耶！耶！\n\n615\n00:55:48.724 --> 00:55:52.394\n令人惊叹的接球 猫头鹰队在坚持\n\n616\n00:55:53.270 --> 00:55:54.521\n来啊 瓦克！\n\n617\n00:55:54.605 --> 00:55:57.149\n乔·戴维还在一垒\n\n618\n00:55:57.232 --> 00:55:59.067\n我看到了！\n我看到了他眼中的恐惧 伙计！\n\n619\n00:55:59.151 --> 00:56:01.653\n来吧 宝贝 来吧 伙计！\n来吧！来吧！就现在！\n\n620\n00:56:01.737 --> 00:56:06.783\n-加油 伙计！加油！加油！\n-来啊 伙计！\n\n621\n00:56:07.701 --> 00:56:10.913\n-加油 伙计！\n-来啊 伙计！\n\n622\n00:56:28.096 --> 00:56:31.767\n-加油！加油！加油！\n-来啊！\n\n623\n00:56:32.184 --> 00:56:33.936\n滑啊！滑啊！\n\n624\n00:56:41.026 --> 00:56:43.779\n-安全！\n-耶！\n\n625\n00:56:44.821 --> 00:56:46.657\n乔·戴维！\n\n626\n00:56:48.909 --> 00:56:50.369\n耶！\n\n627\n00:56:51.537 --> 00:56:54.373\n比格莱克领先\n\n628\n00:56:59.962 --> 00:57:03.507\n鲁迪·博尼拉面临满球数\n\n629\n00:57:03.590 --> 00:57:06.969\n拉夫内克的跑垒员在一垒和二垒\n\n630\n00:57:07.594 --> 00:57:09.721\n来吧拉夫内克队员们 我们能行！\n\n631\n00:57:14.726 --> 00:57:16.353\n四个球\n\n632\n00:57:18.814 --> 00:57:22.484\n现在垒上满是拉夫内克的人\n\n633\n00:57:23.902 --> 00:57:25.612\n就在这儿 鲁迪 就在这儿 就是现在\n\n634\n00:57:25.696 --> 00:57:27.281\n拿下他了！\n\n635\n00:57:27.364 --> 00:57:30.325\n来吧 鲁迪 来 我们能做到\n\n636\n00:57:33.120 --> 00:57:35.747\n-俯视他 鲁迪\n-俯视他\n\n637\n00:57:36.456 --> 00:57:40.669\n去年的区最有价值球员\n科里·琼斯来到了本垒\n\n638\n00:57:40.752 --> 00:57:42.379\n好啊 科里！\n\n639\n00:57:49.553 --> 00:57:52.848\n让他瞧瞧厉害 鲁迪！\n\n640\n00:58:01.857 --> 00:58:03.358\n球！\n\n641\n00:58:13.869 --> 00:58:16.663\n来啊 鲁迪 来啊 宝贝！最后一下！\n\n642\n00:58:16.747 --> 00:58:19.541\n-来啊！\n-来啊！让他出局！\n\n643\n00:58:21.043 --> 00:58:24.713\n-我们来吧 我们来\n-他什么也得不到 什么也没有\n\n644\n00:58:26.507 --> 00:58:29.009\n-快点！\n-来啊！抓紧！抓紧！\n\n645\n00:58:35.349 --> 00:58:36.892\n好球！\n\n646\n00:58:39.811 --> 00:58:44.066\n他现在只能深挖了 计数1-1\n\n647\n00:59:02.251 --> 00:59:04.586\n加油 加油\n\n648\n00:59:04.962 --> 00:59:07.506\n界外球！\n\n649\n00:59:07.589 --> 00:59:09.716\n出界了！\n\n650\n00:59:09.800 --> 00:59:10.843\n球\n\n651\n00:59:10.926 --> 00:59:14.972\n我跟你们说 各位\n他们不会再打出更可怕的界外球了\n\n652\n00:59:15.055 --> 00:59:17.683\n-来啊 鲁迪！来！\n-来啊 鲁迪！你能行！\n\n653\n00:59:17.766 --> 00:59:21.103\n加油 孩子！加油！\n\n654\n00:59:27.067 --> 00:59:29.403\n你说呢 鲁迪？来吧！他赢不了你！\n\n655\n00:59:29.486 --> 00:59:31.027\n-他赢不了你！\n-赢不了！\n\n656\n00:59:31.027 --> 00:59:33.066\n你这次一定能行 伙计！来吧！\n\n657\n00:59:33.156 --> 00:59:34.199\n来吧 快点 快点\n\n658\n00:59:34.283 --> 00:59:35.868\n来吧 鲁迪 只是一次击球 来吧\n\n659\n00:59:35.951 --> 00:59:37.703\n你能行 鲁迪！你能赢他 鲁迪！\n\n660\n00:59:37.786 --> 00:59:40.038\n-来吧 这次你能行！\n-你能赢他！\n\n661\n00:59:40.122 --> 00:59:42.332\n这个废物比不过你 鲁迪！来吧！\n\n662\n00:59:42.416 --> 00:59:44.084\n-你能赢他 鲁迪！\n-他赢不了你！\n\n663\n00:59:44.168 --> 00:59:45.419\n深挖 鲁迪\n\n664\n00:59:45.502 --> 00:59:47.713\n一次就能赢得所有 来吧 鲁迪\n\n665\n00:59:47.796 --> 00:59:50.841\n来吧 鲁迪！你觉得呢？\n让这个家伙出局！来吧！\n\n666\n01:00:07.232 --> 01:00:08.942\n三振出局！\n\n667\n01:00:11.111 --> 01:00:16.200\n猫头鹰赢了！猫头鹰赢了！\n猫头鹰赢了！\n\n668\n01:00:56.031 --> 01:00:58.283\n猫头鹰赢了！猫头鹰赢了！\n\n669\n01:01:38.115 --> 01:01:40.617\n嘿 嘿 嘿 嘿 嘿！安静点 伙计们\n\n670\n01:01:40.701 --> 01:01:42.244\n兄弟们 安静一下\n\n671\n01:01:42.327 --> 01:01:45.330\n那个教会我们追求更多的人\n\n672\n01:01:45.414 --> 01:01:49.751\n区冠军比格莱克猫头鹰队的\n吉米·莫里斯教练！\n\n673\n01:01:52.045 --> 01:01:55.382\n我们追求了 现在我们得到了！\n\n674\n01:01:55.716 --> 01:01:57.593\n耶！\n\n675\n01:02:09.271 --> 01:02:11.899\n现在轮到你了 教练\n\n676\n01:02:18.276 --> 01:02:19.487\n轮到你了 教练\n\n677\n01:02:25.787 --> 01:02:27.456\n轮到你了 教练\n\n678\n01:02:27.915 --> 01:02:30.834\n轮到你了 教练\n\n679\n01:02:33.003 --> 01:02:35.214\n-轮到你了 教练\n-轮到你了 教练\n\n680\n01:02:38.274 --> 01:02:39.455\n轮到你了 教练\n\n681\n01:02:40.594 --> 01:02:44.932\n-轮到你了 教练\n-轮到你了 教练\n\n682\n01:03:04.743 --> 01:03:08.663\n<i>轮到你了 教练！</i>\n\n683\n01:03:15.420 --> 01:03:17.589\n来吧\n\n684\n01:03:17.673 --> 01:03:20.397\n吃你的麦片吧 来 来\n\n685\n01:03:20.397 --> 01:03:22.809\n夏季登记的第一天 我不吃早饭了\n\n686\n01:03:22.886 --> 01:03:25.347\n妈咪 你可以带上一些三明治\n如果你愿意的话\n\n687\n01:03:25.430 --> 01:03:27.808\n他是个船长 杰茜 不要降低他的头衔\n\n688\n01:03:27.891 --> 01:03:30.519\n还是谢谢了 亲爱的\n\n689\n01:03:30.602 --> 01:03:32.187\n你今天有什么计划吗？\n\n690\n01:03:33.814 --> 01:03:35.785\n我吗？\n\n691\n01:03:35.785 --> 01:03:36.574\n没有\n\n692\n01:03:36.653 --> 01:03:38.309\n我们得去见见那个做房地产的人\n\n693\n01:03:38.388 --> 01:03:40.241\n他永远都是船长了\n\n694\n01:03:40.320 --> 01:03:41.697\n为什么人们不给他更好的头衔呢？\n\n695\n01:03:41.780 --> 01:03:43.907\n你是说 比如克朗奇海军上将吗？\n\n696\n01:03:43.991 --> 01:03:45.909\n回答 “是的 女士”\n我就知道你听到我说的话了\n\n697\n01:03:45.993 --> 01:03:50.289\n-是的 女士\n-如果你走的话把他们都带上\n\n698\n01:03:52.708 --> 01:03:54.126\n孩子们听你的话\n\n699\n01:03:54.209 --> 01:03:57.337\n如果我们出去的话\n提醒我别忘了杰米\n\n700\n01:04:00.217 --> 01:04:04.692\n<i>圣安吉洛 156公里</i>\n\n701\n01:04:25.866 --> 01:04:28.035\n他们有很多球员啊 爸爸\n\n702\n01:05:02.956 --> 01:05:04.245\n在这儿签字\n\n703\n01:05:06.490 --> 01:05:08.514\n让你的队员排成队 教练\n大家都得签字\n\n704\n01:05:08.514 --> 01:05:12.782\n-吉米·莫里斯\n-戴夫·帕特森\n\n705\n01:05:12.871 --> 01:05:14.581\n密尔瓦基酿酒人选拔你的时候\n我见过你\n\n706\n01:05:14.665 --> 01:05:16.124\n-对\n-应该有段…\n\n707\n01:05:16.208 --> 01:05:18.252\n-有段时间了\n-对\n\n708\n01:05:18.335 --> 01:05:20.546\n-你怎么样 戴夫？\n-挺好的\n\n709\n01:05:20.629 --> 01:05:23.632\n你还在选球员吗？\n\n710\n01:05:24.091 --> 01:05:27.886\n选球员容易 选好球员却很难\n\n711\n01:05:27.970 --> 01:05:31.139\n你带了几个孩子过来？\n除你的孩子外？\n\n712\n01:05:32.808 --> 01:05:35.769\n-我是为我自己来的\n-为你？\n\n713\n01:05:37.271 --> 01:05:39.731\n好吧\n\n714\n01:05:39.815 --> 01:05:42.317\n-见到你很高兴\n-挺好的 见到你很高兴\n\n715\n01:05:42.401 --> 01:05:43.777\n在这儿签字\n\n716\n01:05:57.082 --> 01:06:01.753\n好了 咱们走吧 让一下\n\n717\n01:06:34.036 --> 01:06:37.414\n-爸爸 这次你可以是X了\n-好\n\n718\n01:06:56.016 --> 01:06:57.726\n好啦 好啦\n\n719\n01:06:59.353 --> 01:07:00.938\n这是最后一片尿布了\n\n720\n01:07:01.021 --> 01:07:03.857\n好吧 我们要走了\n等杰米一准备好就走\n\n721\n01:07:03.941 --> 01:07:06.777\n-但是 爸爸\n-没有但是 好吗？\n\n722\n01:07:06.860 --> 01:07:09.488\n我现在要应付的人已经够多了\n\n723\n01:07:09.780 --> 01:07:12.449\n坚持一下 宝贝 爸爸快好了\n\n724\n01:07:16.036 --> 01:07:19.790\n亨特 我答应了要试试\n\n725\n01:07:19.873 --> 01:07:22.793\n如果他们练看都不看我\n我就什么都做不了\n\n726\n01:07:22.876 --> 01:07:26.755\n嘿 吉米！来吧 到你了\n\n727\n01:07:30.050 --> 01:07:32.386\n好 稍等一下！\n\n728\n01:07:33.799 --> 01:07:34.889\n我可不干\n\n729\n01:07:36.849 --> 01:07:39.935\n好吧 你就坐在这儿\n\n730\n01:07:40.018 --> 01:07:41.812\n看着你的妹妹 好吗？\n\n731\n01:07:41.895 --> 01:07:43.730\n来吧 咱们走\n\n732\n01:07:49.862 --> 01:07:51.530\n坐下！\n\n733\n01:07:54.825 --> 01:07:56.118\n马上就回来\n\n734\n01:08:02.499 --> 01:08:05.252\n现在轮到谁了？好 好\n\n735\n01:08:10.132 --> 01:08:14.178\n-你需要热身吗？\n-不用 我很好\n\n736\n01:08:14.261 --> 01:08:17.180\n好吧 别伤到自己\n\n737\n01:08:22.810 --> 01:08:25.564\n你准备好了就随时开始！\n\n738\n01:08:28.483 --> 01:08:30.861\n只要我准备好了\n\n739\n01:09:32.673 --> 01:09:35.634\n-你想让我继续吗？\n-再来几个！\n\n740\n01:10:31.815 --> 01:10:34.026\n很好 吉米\n\n741\n01:10:41.491 --> 01:10:43.702\n投手 投手\n\n742\n01:10:43.785 --> 01:10:45.704\n兄弟 你让这儿热闹起来了\n\n743\n01:10:45.787 --> 01:10:48.373\n-算了吧\n-你让他们讨论起来了\n\n744\n01:10:48.624 --> 01:10:52.127\n你让他们讨论起来了 好样的 兄弟\n\n745\n01:10:53.212 --> 01:10:55.047\n那是杰茜卡\n\n746\n01:10:59.051 --> 01:11:02.346\n-吉米\n-你很棒 兄弟\n\n747\n01:11:02.429 --> 01:11:05.474\n15年前你能投多快？\n\n748\n01:11:07.434 --> 01:11:10.145\n挺慢的 球探甚至不会用快这个词\n\n749\n01:11:10.229 --> 01:11:16.026\n-吉米 你以前投多快？\n-我不知道 137 138吧 怎么了？\n\n750\n01:11:16.109 --> 01:11:19.590\n你刚才投出了每小时160公里的速度\n\n751\n01:11:19.590 --> 01:11:20.429\n不会吧\n\n752\n01:11:20.513 --> 01:11:23.617\n十二个直投 三个雷达枪\n\n753\n01:11:23.700 --> 01:11:27.120\n-测出的速度都一样\n-不 戴夫 不可能\n\n754\n01:11:27.204 --> 01:11:29.540\n我做球探很长时间了\n\n755\n01:11:29.623 --> 01:11:32.751\n第一条规矩就是\n年龄越老 速度就越慢\n\n756\n01:11:32.835 --> 01:11:34.711\n听着 吉米 如果我报告说\n\n757\n01:11:34.795 --> 01:11:37.923\n我找到了一个\n年龄几乎是这些孩子两倍的人\n\n758\n01:11:38.006 --> 01:11:39.216\n我会被嘲笑的\n\n759\n01:11:39.299 --> 01:11:42.761\n但是如果我不报告\n每小时160公里的快球 我会被辞退的\n\n760\n01:11:42.845 --> 01:11:46.849\n只是想让你知道\n你有可能会接到电话\n\n761\n01:11:51.478 --> 01:11:56.525\n你弄明白我今天看到你多好的表现\n就跟我联系 好吧？\n\n762\n01:11:56.831 --> 01:11:57.674\n好\n\n763\n01:12:31.059 --> 01:12:33.437\n亲爱的 别做晚饭了\n我们要买些披萨\n\n764\n01:12:33.520 --> 01:12:35.147\n谢天谢地\n\n765\n01:12:35.230 --> 01:12:38.358\n吉米 我是坦帕湾魔鬼鱼的丹·乔丹\n\n766\n01:12:38.442 --> 01:12:40.402\n我稍后再打给你\n\n767\n01:12:41.570 --> 01:12:44.698\n吉米 我是坦帕湾魔鬼鱼的\n马克·拉夫斯\n\n768\n01:12:44.781 --> 01:12:46.742\n戴夫·帕特森告诉了我今天下午的事\n\n769\n01:12:46.825 --> 01:12:49.036\n我明早第一件事就是给你做测试\n\n770\n01:12:50.078 --> 01:12:52.956\n嘿 吉米 我是戴夫 听着\n我们会让你在接下来的几天\n\n771\n01:12:53.040 --> 01:12:54.166\n再投一次以便确认\n\n772\n01:12:54.249 --> 01:12:56.084\n坦帕会过来几个人\n\n773\n01:13:03.050 --> 01:13:05.427\n妈妈！\n\n774\n01:13:09.056 --> 01:13:12.851\n爸爸告诉我把披萨给你\n别的什么也不要说\n\n775\n01:13:13.685 --> 01:13:19.441\n谢谢 亲爱的 我确定他就是这么说的\n\n776\n01:13:21.109 --> 01:13:23.612\n好吧 好吧 说吧\n\n777\n01:13:26.281 --> 01:13:28.909\n那里有大约一千个球员 天很热\n\n778\n01:13:28.992 --> 01:13:30.702\n爸爸投得很用力\n\n779\n01:13:30.786 --> 01:13:31.995\n-噢 是吗？\n-是啊\n\n780\n01:13:32.079 --> 01:13:34.414\n-天很热 但是很有意思\n-是啊\n\n781\n01:13:34.498 --> 01:13:36.291\n-我的鼻子被严重晒伤了\n-对\n\n782\n01:13:38.460 --> 01:13:41.713\n那个人还认为雷达枪坏了\n\n783\n01:13:42.840 --> 01:13:47.469\n你知道有多少人能投出\n每小时160公里的球吗？\n\n784\n01:13:47.553 --> 01:13:50.597\n-没多少吧？\n-用一只手就能数得出来\n\n785\n01:13:50.681 --> 01:13:52.766\n我仍然不敢相信 我是说…\n\n786\n01:13:52.850 --> 01:13:55.352\n我们留言机上的那些人\n都是大联盟的球探\n\n787\n01:13:55.435 --> 01:13:58.146\n我知道 这很棒\n\n788\n01:14:01.108 --> 01:14:03.485\n听着 亲爱的\n为什么你不告诉我这一切呢？\n\n789\n01:14:03.569 --> 01:14:07.322\n-我只是觉得你会嘲笑我\n-才不会\n\n790\n01:14:07.406 --> 01:14:08.407\n就是这事儿让孩子们开始继续打球\n\n791\n01:14:11.743 --> 01:14:15.163\n我以为我只是去那儿投几个球\n这事儿就结束了\n\n792\n01:14:24.464 --> 01:14:28.760\n-所以你在考虑这件事吗？\n-我不知道\n\n793\n01:14:31.305 --> 01:14:36.935\n我不知道\n我以前从没这么用力投球过\n\n794\n01:14:41.426 --> 01:14:42.890\n怎么了？\n\n795\n01:14:46.570 --> 01:14:48.530\n你看起来不是很兴奋\n\n796\n01:14:48.614 --> 01:14:51.783\n不 我很兴奋 真的\n\n797\n01:14:55.746 --> 01:14:59.333\n这是个艰难的决定\n你会让一个左撇子中继投手\n\n798\n01:14:59.416 --> 01:15:02.586\n去对付左撇子击球手吗？\n\n799\n01:15:02.669 --> 01:15:05.964\n没错 汤姆 他们有约翰逊 也有比索\n\n800\n01:15:06.048 --> 01:15:08.717\n他在周二晚上打了整整一局\n\n801\n01:15:08.800 --> 01:15:10.719\n好吧 现在看来他们已经下定决心了\n\n802\n01:15:10.802 --> 01:15:12.429\n他们要按计划行事了\n\n803\n01:15:12.513 --> 01:15:13.931\n格雷从候补区出来\n\n804\n01:15:14.014 --> 01:15:17.142\n以传统方式跑过外场来到投手丘\n\n805\n01:15:17.226 --> 01:15:20.354\n吉姆 我敢确定无论你这么跑多少次\n\n806\n01:15:20.437 --> 01:15:22.940\n都会刺激人心\n\n807\n01:15:23.023 --> 01:15:25.651\n你说得对 吉姆 回到行动上来\n\n808\n01:16:12.447 --> 01:16:15.284\n这个没有问题\n\n809\n01:16:32.593 --> 01:16:35.262\n他的手臂会受影响吗？\n\n810\n01:17:14.801 --> 01:17:17.262\n-吉米？\n-是的 长官\n\n811\n01:17:17.346 --> 01:17:21.850\n我刚刚开车经过 看到你的灯亮着\n\n812\n01:17:21.934 --> 01:17:24.603\n还会再亮几个小时\n\n813\n01:17:25.938 --> 01:17:27.606\n-你想进来吗？\n-不 不用了\n\n814\n01:17:27.689 --> 01:17:31.026\n我正要…我要回去了\n\n815\n01:17:31.735 --> 01:17:34.404\n我只是想…\n\n816\n01:17:36.657 --> 01:17:39.576\n-罗莉打过电话了\n-哈？\n\n817\n01:17:39.660 --> 01:17:42.579\n我想球探看到了他们想要的投球\n\n818\n01:17:44.122 --> 01:17:47.084\n我不知道要怎么办\n\n819\n01:17:48.544 --> 01:17:51.129\n给自己点时间\n\n820\n01:17:51.630 --> 01:17:54.633\n我没有太多时间\n\n821\n01:17:57.469 --> 01:18:00.138\n你在问我吗？\n\n822\n01:18:03.559 --> 01:18:05.269\n是的 先生\n\n823\n01:18:12.067 --> 01:18:15.737\n你爷爷曾告诉我\n\n824\n01:18:15.821 --> 01:18:19.157\n想想你想做什么是可以的\n\n825\n01:18:19.241 --> 01:18:22.452\n直到是时候开始做你注定要做的事\n\n826\n01:18:25.080 --> 01:18:27.749\n这可能不是你想听到的\n\n827\n01:18:44.600 --> 01:18:47.186\n-晚安 吉米\n-晚安\n\n828\n01:19:03.869 --> 01:19:06.705\n我发誓 有时我觉得 他晚上躺在床上\n\n829\n01:19:06.788 --> 01:19:10.626\n只琢磨一件事\n就是怎么能说出最伤人的话\n\n830\n01:19:10.709 --> 01:19:14.213\n我差点就以为他会给我一些好建议\n\n831\n01:19:14.963 --> 01:19:16.965\n也许他已经给了\n\n832\n01:19:17.883 --> 01:19:19.218\n什么？\n\n833\n01:19:20.177 --> 01:19:24.223\n听着 吉米 我爱你\n\n834\n01:19:24.431 --> 01:19:25.974\n上帝知道 我认为你去那里\n\n835\n01:19:26.058 --> 01:19:28.060\n带着孩子们去参加选拔 这都可以\n\n836\n01:19:28.143 --> 01:19:30.812\n但是我有点担心\n你可能忽略了一个事实\n\n837\n01:19:30.896 --> 01:19:32.397\n你有需要你的家人\n\n838\n01:19:32.481 --> 01:19:35.234\n有一份相当体面的工作\n在沃思堡等着你\n\n839\n01:19:35.317 --> 01:19:38.278\n事先声明 好吧\n我从没说过我要去打棒球\n\n840\n01:19:38.362 --> 01:19:39.404\n算了吧 吉米 我了解你\n\n841\n01:19:39.488 --> 01:19:42.267\n但是我确实希望\n能获得家庭的一些支持\n\n842\n01:19:42.267 --> 01:19:45.455\n所以这不涉及到我和孩子们吗？\n\n843\n01:19:45.536 --> 01:19:47.287\n你不能靠梦想吃饭 吉米\n\n844\n01:19:47.371 --> 01:19:50.791\n它们也不会为衣服 鞋 煤气\n或者保姆付钱\n\n845\n01:19:50.874 --> 01:19:52.668\n我不想在这件事上做个坏人\n\n846\n01:19:52.751 --> 01:19:54.461\n但是这儿得有个人保持理智\n\n847\n01:19:54.545 --> 01:19:56.922\n你知道吗？这就是我的全部生活！\n\n848\n01:19:57.005 --> 01:20:01.760\n那我的生活呢？我也在场 记得吗？\n\n849\n01:20:01.844 --> 01:20:04.012\n每次你受伤 我就坐在前排座位上\n\n850\n01:20:04.096 --> 01:20:07.599\n看着你自闭\n\n851\n01:20:07.683 --> 01:20:09.351\n也与我隔绝\n\n852\n01:20:12.855 --> 01:20:15.524\n事实是 你退出时我很开心\n\n853\n01:20:19.027 --> 01:20:20.612\n开心\n\n854\n01:20:22.990 --> 01:20:24.157\n对\n\n855\n01:20:25.993 --> 01:20:29.079\n因为我不想再看到你受伤了\n\n856\n01:22:08.887 --> 01:22:12.224\n-孩子睡了吗？\n-至少睡了有一会儿了\n\n857\n01:22:16.270 --> 01:22:18.480\n对不起\n\n858\n01:22:18.564 --> 01:22:20.649\n我也是\n\n859\n01:22:24.069 --> 01:22:26.655\n-我在想…\n-我也是 我觉得你应该去\n\n860\n01:22:26.738 --> 01:22:29.825\n-不 不 你说得对\n-不\n\n861\n01:22:30.450 --> 01:22:32.244\n我不对\n\n862\n01:22:37.749 --> 01:22:41.128\n我们这个家里有个八岁的男孩儿\n\n863\n01:22:41.211 --> 01:22:43.255\n无论阴天晴天 整天都在等着\n\n864\n01:22:43.338 --> 01:22:47.134\n等着看他的爸爸能做出什么\n别人认为他做不到的事\n\n865\n01:22:48.677 --> 01:22:54.183\n如果你现在不试试\n我们要怎么跟他说呢？\n\n866\n01:23:05.777 --> 01:23:09.072\n我不能把你和这里的一切抛下\n\n867\n01:23:09.156 --> 01:23:10.949\n吉米·莫里斯 我是得克萨斯的女人\n\n868\n01:23:11.033 --> 01:23:15.078\n我不需要男人的帮助\n就能让生活正常运转\n\n869\n01:23:17.831 --> 01:23:19.458\n好吗？\n\n870\n01:23:30.219 --> 01:23:32.095\n好\n\n871\n01:23:37.768 --> 01:23:38.977\n很好\n\n872\n01:24:22.312 --> 01:24:25.440\n再见了 小伙子\n\n873\n01:25:18.399 --> 01:25:22.239\n<i>佛罗里达州奥兰多 AA南方联盟</i>\n\n874\n01:25:37.262 --> 01:25:39.806\n借过\n\n875\n01:25:39.806 --> 01:25:40.974\n借过\n\n876\n01:25:45.938 --> 01:25:49.233\n-你是那个老伙计？\n-我是\n\n877\n01:25:51.360 --> 01:25:53.820\n加油 赖斯 你连胜了\n\n878\n01:25:55.364 --> 01:25:57.032\n巅峰\n\n879\n01:25:57.115 --> 01:26:00.452\n你用助步器去投手丘\n还是让其他球员背着你？\n\n880\n01:26:00.536 --> 01:26:03.705\n嘿 投手 你想追上谁？参议员吗？\n\n881\n01:26:03.789 --> 01:26:07.793\n他们给你多少钱？\n让我们来看你 他们应该给我们钱！\n\n882\n01:26:07.876 --> 01:26:09.336\n欢迎来到最后一站！\n\n883\n01:26:11.964 --> 01:26:15.425\n嘿 队长！我可不知道\n今晚要带着爸爸来工作\n\n884\n01:26:22.599 --> 01:26:24.142\n真是提高了他的平均水平！\n\n885\n01:26:24.642 --> 01:26:26.375\n-时间到！\n-奥兰多队换投手\n\n886\n01:26:27.396 --> 01:26:32.734\n现在投球的是 九号 约翰尼·莫里斯\n\n887\n01:26:32.818 --> 01:26:35.153\n更正一下 吉米·莫里斯\n\n888\n01:26:35.237 --> 01:26:39.199\n现在 球迷们\n是时候猜猜哪个车获胜了！\n\n889\n01:26:39.283 --> 01:26:42.578\n在一垒线发生了大型车祸！\n\n890\n01:26:42.870 --> 01:26:45.581\n这次一号会赢\n\n891\n01:26:45.664 --> 01:26:47.791\n这人是谁？\n\n892\n01:26:47.875 --> 01:26:50.252\n快点 我们要坐很长时间的车\n\n893\n01:26:50.794 --> 01:26:54.006\n我们开始吧 斯丁格雷斯\n\n894\n01:27:21.074 --> 01:27:26.079\n嘿 投手！我看起来像好球区吗？\n\n895\n01:27:26.538 --> 01:27:27.956\n你太逊了！\n\n896\n01:27:29.458 --> 01:27:31.960\n难以相信\n他们让你在你的首场比赛上投球了\n\n897\n01:27:32.044 --> 01:27:34.546\n-你怎么样？\n-挺好的\n\n898\n01:27:37.090 --> 01:27:39.301\n我让他们中的一些人逃脱了\n\n899\n01:27:39.384 --> 01:27:40.719\n你跑进去的时候球迷们都呐喊了吗？\n\n900\n01:27:40.802 --> 01:27:43.180\n是啊 对 是的 他们欢呼了 没错\n\n901\n01:27:43.680 --> 01:27:46.266\n亲爱的 真好 我去叫孩子们\n\n902\n01:27:46.350 --> 01:27:48.060\n不用了\n\n903\n01:27:48.143 --> 01:27:51.980\n告诉他们我明天给他们打电话\n不管我们在哪儿\n\n904\n01:27:52.064 --> 01:27:55.317\n好 我会的\n\n905\n01:27:57.986 --> 01:27:59.404\n我爱你\n\n906\n01:28:02.241 --> 01:28:05.953\n-我也爱你\n-保重\n\n907\n01:29:47.095 --> 01:29:48.305\n暂停！\n\n908\n01:29:48.642 --> 01:29:50.351\n<i>北卡罗莱纳州达勒姆 AAA国际联盟</i>\n\n909\n01:29:50.432 --> 01:29:53.268\n-四乘以四是多少？\n-十七吗？\n\n910\n01:29:53.352 --> 01:29:58.482\n不 不是十七 你是在猜 加起来\n\n911\n01:29:59.650 --> 01:30:01.276\n-十六？\n-是十六\n\n912\n01:30:01.360 --> 01:30:03.779\n你要做到看到四乘以四\n\n913\n01:30:03.862 --> 01:30:06.865\n就知道那是十六 而不用再想\n\n914\n01:30:06.949 --> 01:30:08.283\n好吧？\n\n915\n01:30:08.367 --> 01:30:11.370\n-现在 让我们来算五\n-爸爸 我已经算过五了\n\n916\n01:30:11.453 --> 01:30:13.413\n什么…\n\n917\n01:30:17.709 --> 01:30:19.211\n如果你想学会怎么乘\n\n918\n01:30:19.294 --> 01:30:20.712\n你就得练习 伙计\n\n919\n01:30:20.796 --> 01:30:22.089\n好吧\n\n920\n01:30:22.172 --> 01:30:24.258\n-爸爸\n-怎么了？\n\n921\n01:30:24.341 --> 01:30:27.219\n告诉你什么时候能去大联盟了吗？\n\n922\n01:30:29.638 --> 01:30:32.850\n-你能让妈妈接电话吗？\n-好\n\n923\n01:30:32.933 --> 01:30:34.309\n好\n\n924\n01:30:38.772 --> 01:30:41.149\n谢谢 亲爱的\n\n925\n01:30:41.233 --> 01:30:42.401\n喂\n\n926\n01:30:42.484 --> 01:30:44.736\n杰茜说他们让你投了很多球\n\n927\n01:30:44.820 --> 01:30:49.032\n杰茜需要学会怎么保守爸爸的秘密\n\n928\n01:30:49.116 --> 01:30:51.410\n-怎么样？\n-一切顺利\n\n929\n01:30:51.493 --> 01:30:54.162\n亨特周五要去野外旅行\n我们剩下的人在讨论…\n\n930\n01:30:54.246 --> 01:30:56.123\n亲爱的 我不是这个意思\n\n931\n01:30:56.206 --> 01:31:01.253\n我知道 还行 我们有点落后了\n\n932\n01:31:01.336 --> 01:31:02.421\n落后多少？\n\n933\n01:31:02.504 --> 01:31:06.008\n他们拿走了床 却留下了床头柜\n\n934\n01:31:11.138 --> 01:31:15.267\n-你还好吗？\n-我就是累了\n\n935\n01:31:15.350 --> 01:31:17.477\n-我爱你\n-我也爱你\n\n936\n01:31:17.561 --> 01:31:20.105\n-晚安 晚安\n-好吧 晚安\n\n937\n01:31:28.447 --> 01:31:29.323\n听着 兄弟\n\n938\n01:31:29.406 --> 01:31:31.950\n这是我们这儿的酒店唯一的长途电话\n\n939\n01:31:32.034 --> 01:31:36.205\n你看到有人在等\n就控制在10分钟以内好吗？\n\n940\n01:31:38.332 --> 01:31:41.418\n什么？现在你说完了？\n\n941\n01:31:42.669 --> 01:31:45.339\n都用在你女朋友身上了？\n\n942\n01:31:47.466 --> 01:31:51.720\n那是我儿子 他做作业需要帮助\n\n943\n01:32:02.231 --> 01:32:03.899\n出去\n\n944\n01:32:04.775 --> 01:32:08.195\n看来似乎肯尼·贾斯廷要上镜了\n\n945\n01:32:12.866 --> 01:32:16.537\n吉米！嘿吉米 过来一会儿\n\n946\n01:32:20.624 --> 01:32:23.126\n吉米 我想让你见见\nABC新闻的蒂姆·斯图尔特\n\n947\n01:32:23.210 --> 01:32:24.253\n-嗨 吉米\n-我很荣幸\n\n948\n01:32:24.336 --> 01:32:26.797\n谢谢给我们一些时间 你想坐下吗？\n\n949\n01:32:26.880 --> 01:32:28.632\n给你拿了一件运动衫\n\n950\n01:32:29.758 --> 01:32:31.635\n你能相信吗？\n\n951\n01:32:31.718 --> 01:32:33.679\n我昨晚四比五 四处看哪里有摄像头\n\n952\n01:32:33.762 --> 01:32:36.265\n他投球投得太好了 值得讨论\n\n953\n01:32:36.348 --> 01:32:39.434\n他年龄倒是挺大 得讨论一下退役了\n\n954\n01:32:41.489 --> 01:32:47.844\n<i>给爸爸的爱 杰茜</i>\n\n955\n01:33:13.468 --> 01:33:15.470\n走吧 我们走\n\n956\n01:33:19.474 --> 01:33:21.268\n拿着我的杂志\n\n957\n01:33:33.280 --> 01:33:36.033\n老头队员 你动作有点慢\n\n958\n01:33:36.116 --> 01:33:38.744\n是啊 坐六小时的公交\n\n959\n01:33:38.827 --> 01:33:41.663\n-是吗？\n-不要紧\n\n960\n01:33:41.747 --> 01:33:44.833\n走吧 兄弟 我正好有放松筋骨的方法\n\n961\n01:33:52.174 --> 01:33:53.509\n给你\n\n962\n01:33:57.513 --> 01:34:01.266\n先生们 为让贝比·鲁斯\n进入名人堂的食谱干杯\n\n963\n01:34:01.350 --> 01:34:04.353\n河 看贝比打棒球是什么感觉？\n\n964\n01:34:05.270 --> 01:34:07.689\n你确定你想聊这个吗？\n\n965\n01:34:07.773 --> 01:34:10.817\n当你们把票价提到50美分时\n你们失去了多少球迷？\n\n966\n01:34:10.901 --> 01:34:13.237\n没有你投球时我们输的次数那么多\n\n967\n01:34:14.571 --> 01:34:16.198\n聊天结束了\n\n968\n01:34:16.281 --> 01:34:20.285\n河 我发誓 如果你一直这么幽默\n没人会说什么…\n\n969\n01:34:22.962 --> 01:34:24.097\n说什么？\n\n970\n01:34:27.626 --> 01:34:29.378\n什么意思？\n\n971\n01:34:30.128 --> 01:34:33.048\n他们说什么了 布鲁克斯？\n\n972\n01:34:33.131 --> 01:34:35.092\n有些家伙认为\n\n973\n01:34:35.175 --> 01:34:38.095\n球队宣传你的故事的方式 这一切…\n\n974\n01:34:38.720 --> 01:34:42.099\n他们觉得我是某种宣传的噱头吗？\n\n975\n01:34:42.850 --> 01:34:46.603\n这就是他们所想的？\n他们认为我抢了别人的位置\n\n976\n01:34:49.147 --> 01:34:52.401\n你觉得呢 布鲁克斯？\n\n977\n01:34:53.360 --> 01:34:56.655\n你的投球速度对我来说很快\n我就知道这个\n\n978\n01:35:03.871 --> 01:35:06.206\n冲啊 布鲁克斯！这就是差距！\n\n979\n01:35:06.290 --> 01:35:07.291\n冲 冲 冲 冲 冲！\n\n980\n01:35:07.374 --> 01:35:10.043\n-一直冲 布鲁克斯！\n-加油 布鲁克斯！\n\n981\n01:35:11.128 --> 01:35:14.089\n安全！不要着急！\n\n982\n01:35:14.173 --> 01:35:16.675\n-你想热身吗？\n-干得好 布鲁克斯！\n\n983\n01:35:16.758 --> 01:35:18.844\n-是啊\n-别想着涨价 布鲁克斯！\n\n984\n01:35:18.927 --> 01:35:20.304\n一点点！\n\n985\n01:35:22.890 --> 01:35:29.188\n现在给公牛队击球的是\n38号 肯尼·布莱尔森\n\n986\n01:35:48.999 --> 01:35:52.753\n马克 我们都知道 应该是布鲁克斯\n\n987\n01:35:52.836 --> 01:35:55.797\n我以前招过不止一个球员\n\n988\n01:35:55.881 --> 01:35:57.633\n有人是我这个年龄吗？\n\n989\n01:35:59.968 --> 01:36:01.553\n所以 你怎么想？\n\n990\n01:36:01.637 --> 01:36:06.391\n我在家有许多账单要付\n我在那里有份很好的工作\n\n991\n01:36:06.475 --> 01:36:08.769\n我在这儿一个月只赚600美元\n\n992\n01:36:08.852 --> 01:36:11.980\n而且我三个月没见家人了\n\n993\n01:36:12.064 --> 01:36:14.024\n我们还有几个赛季\n\n994\n01:36:17.945 --> 01:36:21.615\n有人曾告诉我\n考虑一下你想做什么 这没什么\n\n995\n01:36:21.698 --> 01:36:25.244\n直到是时候开始做你注定要做的事\n\n996\n01:36:27.329 --> 01:36:30.874\n要知道 你是我过去一个月\n最好的替补投手\n\n997\n01:36:37.422 --> 01:36:40.133\n谢谢 马克\n\n998\n01:36:48.725 --> 01:36:51.979\n-杰茜卡 给我！那是我的！\n-不 亨特\n\n999\n01:36:52.062 --> 01:36:55.148\n我要告诉妈妈了！快点\n\n1000\n01:36:55.232 --> 01:36:56.733\n-我的 我的 那一直是我的\n-杰米睡了\n\n1001\n01:36:56.817 --> 01:36:59.319\n-你会有大麻烦的\n-喂？\n\n1002\n01:36:59.403 --> 01:37:01.321\n-喂\n-喂！\n\n1003\n01:37:01.405 --> 01:37:04.157\n我还以为明天才会接到你的电话\n\n1004\n01:37:05.200 --> 01:37:06.785\n我要回家了\n\n1005\n01:37:09.329 --> 01:37:11.248\n-什么？你受伤了吗？\n-没有\n\n1006\n01:37:11.331 --> 01:37:15.794\n我很好 只是是时候了\n\n1007\n01:37:15.878 --> 01:37:22.509\n-你给沃思堡打电话了 是吗？\n-我告诉他们我两周之内报到\n\n1008\n01:37:23.468 --> 01:37:29.016\n-所以再投两周球\n-不 还有很多你需要做的\n\n1009\n01:37:29.099 --> 01:37:30.559\n我来处理\n\n1010\n01:37:30.642 --> 01:37:31.685\n-这三个月我们挺好的\n-罗莉 罗莉？\n\n1011\n01:37:31.768 --> 01:37:34.188\n两周我们也没问题的\n\n1012\n01:37:36.815 --> 01:37:39.985\n不 我在这里是浪费时间\n\n1013\n01:37:41.445 --> 01:37:42.946\n听着 吉米\n\n1014\n01:37:43.030 --> 01:37:46.450\n天知道 我当然希望你尽快回家睡\n\n1015\n01:37:47.075 --> 01:37:48.202\n但是如果你要回来\n\n1016\n01:37:48.285 --> 01:37:50.162\n你得保证是出于正确的原因\n\n1017\n01:37:50.245 --> 01:37:53.790\n因为你才是那个要面对这一切的人\n好吗？\n\n1018\n01:37:53.874 --> 01:37:57.211\n-我会没事的\n-你还爱投球吗？\n\n1019\n01:38:02.132 --> 01:38:03.842\n好好考虑一下 好吗？\n\n1020\n01:38:13.060 --> 01:38:15.229\n最后 在今晚 梦想不死\n\n1021\n01:38:15.312 --> 01:38:18.398\n1983年 密尔瓦基酿酒人选拔了\n一个名叫吉米·莫里斯的投手\n\n1022\n01:38:18.482 --> 01:38:20.442\n之后你再也没听说过他\n因为他胳膊出了问题\n\n1023\n01:38:20.526 --> 01:38:23.237\n他很快就放弃了棒球 结婚 有了孩子\n\n1024\n01:38:23.320 --> 01:38:25.572\n在高中教化学\n\n1025\n01:38:25.656 --> 01:38:28.617\n训练高中孩子们做击球投球练习\n\n1026\n01:38:28.700 --> 01:38:31.703\n他发现他投出的球每小时160公里\n\n1027\n01:38:31.787 --> 01:38:34.540\n比他几年前投出的要快\n\n1028\n01:38:34.831 --> 01:38:38.710\n他不知道这是怎么发生的\n但猜这对他的梦想来说意味着什么？\n\n1029\n01:38:38.794 --> 01:38:40.295\n接下来有请亚伦·布朗\n\n1030\n01:38:40.379 --> 01:38:43.090\n吉米·莫里斯不敢告诉他妈妈\n\n1031\n01:38:43.173 --> 01:38:47.261\n他辞去了高中老师的工作\n\n1032\n01:38:47.344 --> 01:38:49.847\n在职棒小联盟成为一名替补投球手\n\n1033\n01:38:49.930 --> 01:38:52.933\n他年龄很大了\n对于小联盟来说太大了\n\n1034\n01:38:53.016 --> 01:38:55.227\n但是他比他20岁的时候\n投得更用力 也更好\n\n1035\n01:38:57.688 --> 01:39:00.065\n所以他回到了那个名为职棒小联盟的\n\n1036\n01:39:00.148 --> 01:39:01.567\n陌生但奇妙的地方\n\n1037\n01:39:01.650 --> 01:39:04.278\n在那儿\n公牛对每一次本垒打嗤之以鼻\n\n1038\n01:39:04.361 --> 01:39:07.489\n明日之星忙着跑垒 打比赛\n\n1039\n01:39:07.573 --> 01:39:10.742\n我向孩子们发起挑战\n让他们追求梦想\n\n1040\n01:39:10.826 --> 01:39:13.078\n这是为了激励他们\n\n1041\n01:39:13.161 --> 01:39:15.956\n他们把球抛回给我\n\n1042\n01:39:16.039 --> 01:39:19.126\n说我没有追求自己的梦\n\n1043\n01:39:19.209 --> 01:39:21.712\n-他们是很棒的孩子\n-安静点 我在看呢\n\n1044\n01:39:21.795 --> 01:39:23.797\n市里给了我很大的支持\n\n1045\n01:39:23.881 --> 01:39:25.549\n我在那里长大\n\n1046\n01:39:25.632 --> 01:39:29.094\n我从家人和朋友那儿得到了许多支持\n\n1047\n01:39:29.178 --> 01:39:31.597\n还有市里的人\n\n1048\n01:39:31.680 --> 01:39:35.100\n棒球比赛是我生命中的真爱\n\n1049\n01:39:35.184 --> 01:39:39.438\n除了我的妻子 罗莉之外\n我还是个小男孩时就爱上了棒球\n\n1050\n01:39:39.521 --> 01:39:44.026\n当我是个孩子的时候\n我梦想着参加职业棒球赛\n\n1051\n01:39:44.109 --> 01:39:46.570\n我曾经一边投球一边想象\n\n1052\n01:39:46.653 --> 01:39:50.199\n就像每个孩子那样\n想象参加世界职棒大赛\n\n1053\n01:39:50.282 --> 01:39:54.745\n想象在大联盟球场上\n在第七场比赛中的第九局投球\n\n1054\n01:39:54.828 --> 01:39:59.166\n有戏剧性 有悬念\n\n1055\n01:39:59.249 --> 01:40:03.295\n有和其他队员的友情 有球迷\n\n1056\n01:40:03.378 --> 01:40:07.633\n你一点一点想象 那会是很棒的比赛\n\n1057\n01:40:09.384 --> 01:40:11.636\n<i>酒吧</i>\n\n1058\n01:40:41.416 --> 01:40:43.919\n注意 小心\n\n1059\n01:40:46.088 --> 01:40:48.215\n打起精神来 来吧 伙计！\n\n1060\n01:40:55.639 --> 01:40:58.559\n准备好了！\n\n1061\n01:41:14.283 --> 01:41:16.285\n-河！\n-嗨\n\n1062\n01:41:19.663 --> 01:41:22.249\n你知道我们今天要干什么吧\n布鲁克斯？\n\n1063\n01:41:22.332 --> 01:41:24.459\n我们要打棒球\n\n1064\n01:41:26.336 --> 01:41:27.462\n二！\n\n1065\n01:41:34.219 --> 01:41:38.473\n威廉斯计数0-2 莫里斯真的是高手\n\n1066\n01:41:39.016 --> 01:41:40.809\n教练今晚真的很厉害\n\n1067\n01:41:44.897 --> 01:41:47.900\n三振出局 他接住了一个快球\n\n1068\n01:41:47.983 --> 01:41:50.861\n这是莫里斯今晚第三个三振出局了\n\n1069\n01:41:58.702 --> 01:42:02.247\n-内场！\n-我接到了！接到了！\n\n1070\n01:42:17.429 --> 01:42:19.014\n谢谢你今晚帮我收拾残局\n\n1071\n01:42:19.097 --> 01:42:22.392\n嘿 你前七局都投得很好\n这可不是残局\n\n1072\n01:42:25.979 --> 01:42:27.397\n吉米\n\n1073\n01:42:36.740 --> 01:42:38.784\n进来 关上门\n\n1074\n01:42:43.830 --> 01:42:47.167\n吉米 我刚接到大俱乐部的电话\n\n1075\n01:42:48.752 --> 01:42:51.171\n他们选拔了布鲁克斯\n\n1076\n01:42:52.881 --> 01:42:55.300\n很好\n\n1077\n01:42:55.384 --> 01:42:56.844\n他不会回来了\n\n1078\n01:42:56.927 --> 01:42:59.179\n他很尊敬你\n\n1079\n01:42:59.263 --> 01:43:02.766\n我想也许你想成为那个告诉他的人\n\n1080\n01:43:05.727 --> 01:43:08.689\n-好\n-你也要去\n\n1081\n01:43:15.404 --> 01:43:17.614\n他们选拔我了？\n\n1082\n01:43:19.992 --> 01:43:23.245\n今晚你们两个坐上飞机\n明天就能追上队伍\n\n1083\n01:43:27.124 --> 01:43:30.002\n-在哪儿？\n-他们现在在路上了\n\n1084\n01:43:31.420 --> 01:43:33.088\n在得克萨斯\n\n1085\n01:44:08.790 --> 01:44:10.876\n-喂？\n-喂 罗莉\n\n1086\n01:44:10.959 --> 01:44:13.629\n-嗨\n-嗨\n\n1087\n01:44:15.964 --> 01:44:19.676\n你知道那件我从没穿过的\n蓝色运动衫吗？\n\n1088\n01:44:19.760 --> 01:44:22.471\n稍等一下 我在煮东西\n\n1089\n01:44:28.477 --> 01:44:30.187\n说到你没穿过的蓝色运动衫\n怎么了？\n\n1090\n01:44:30.270 --> 01:44:32.523\n你愿意明天把它带到阿灵顿来吗？\n\n1091\n01:44:32.606 --> 01:44:35.859\n阿灵顿？我还以为你在…\n\n1092\n01:44:36.985 --> 01:44:39.655\n你现在就告诉我 吉米·莫里斯\n\n1093\n01:44:41.365 --> 01:44:45.494\n很明显 大联盟是有着装要求的\n\n1094\n01:44:49.498 --> 01:44:52.000\n-罗莉？\n-我在\n\n1095\n01:44:54.670 --> 01:44:57.089\n一小时之内我就要起飞了\n\n1096\n01:44:57.089 --> 01:44:58.590\n你能告诉大家吗？\n\n1097\n01:44:58.674 --> 01:45:02.302\n当然 你只要先告诉一个人就够了\n\n1098\n01:45:02.386 --> 01:45:03.971\n亨特？\n\n1099\n01:45:04.581 --> 01:45:06.695\n你爸爸有些事想告诉你\n\n1100\n01:45:08.809 --> 01:45:10.227\n爸爸\n\n1101\n01:45:10.310 --> 01:45:14.606\n-嘿 伙计 猜猜怎么了？\n-怎么了？\n\n1102\n01:45:15.941 --> 01:45:18.277\n你爸爸要成为大联盟投手了\n\n1103\n01:45:18.360 --> 01:45:19.486\n真的吗？\n\n1104\n01:45:19.570 --> 01:45:22.739\n真的 你觉得怎么样？\n\n1105\n01:45:22.823 --> 01:45:26.076\n-太酷了 我不敢相信\n-好吧\n\n1106\n01:45:26.159 --> 01:45:28.287\n你要为哪个队投球？\n\n1107\n01:45:28.370 --> 01:45:31.540\n-他们叫魔鬼鱼\n-魔鬼鱼是什么？\n\n1108\n01:45:31.832 --> 01:45:35.002\n-是一种鱼\n-它是什么颜色的？\n\n1109\n01:45:35.085 --> 01:45:37.212\n-黑的\n-能吃吗？\n\n1110\n01:45:37.296 --> 01:45:39.464\n我不知道 小伙 它有毒刺\n\n1111\n01:45:39.548 --> 01:45:44.052\n太酷了 我爸爸是大联盟投手\n\n1112\n01:46:37.748 --> 01:46:41.040\n<i>来大联盟看莫里斯教练</i>\n\n1113\n01:46:41.124 --> 01:46:44.206\n<i>今晚7点在阿灵顿球场见</i>\n\n1114\n01:47:17.536 --> 01:47:22.952\n<i>阿灵顿球场</i>\n\n1115\n01:48:07.779 --> 01:48:09.781\n队伍几小时之后才到\n\n1116\n01:48:09.865 --> 01:48:12.159\n你们可以随便转转\n\n1117\n01:48:17.080 --> 01:48:19.875\n我们不在堪萨斯了 对吗 河？\n\n1118\n01:49:05.003 --> 01:49:06.505\n晚上好 女士们 先生们\n\n1119\n01:49:06.588 --> 01:49:09.550\n欢迎来到阿灵顿球场\n\n1120\n01:49:09.633 --> 01:49:12.135\n这是得克萨斯的棒球时刻\n\n1121\n01:49:12.219 --> 01:49:14.513\n今晚的比赛是 坦帕湾魔鬼鱼\n\n1122\n01:49:14.596 --> 01:49:17.975\n对战得州游骑兵\n\n1123\n01:49:56.889 --> 01:49:59.892\n吉米！吉米·莫里斯！\n\n1124\n01:49:59.975 --> 01:50:01.101\n爸爸！\n\n1125\n01:50:06.690 --> 01:50:08.650\n-嗨 爸爸\n-嗨\n\n1126\n01:50:11.862 --> 01:50:12.863\n你看起来状态很好\n\n1127\n01:50:13.864 --> 01:50:15.699\n孩子们 你们的爸爸\n看起来状态很好 对吧？\n\n1128\n01:50:15.782 --> 01:50:17.367\n-是\n-是啊\n\n1129\n01:50:20.537 --> 01:50:22.289\n-嗨\n-嗨\n\n1130\n01:50:22.372 --> 01:50:24.333\n我难以相信\n\n1131\n01:50:26.418 --> 01:50:28.337\n-嘿 亲爱的\n-嗨 爸爸\n\n1132\n01:50:28.795 --> 01:50:30.380\n-你看上去块头很大了\n-是啊\n\n1133\n01:50:31.048 --> 01:50:32.508\n我的搭档\n\n1134\n01:50:33.258 --> 01:50:35.177\n-我很想你\n-我也是\n\n1135\n01:50:36.178 --> 01:50:39.848\n这是今晚比赛的首发阵容\n\n1136\n01:50:41.850 --> 01:50:44.269\n孩子们 我们该让爸爸去工作了\n\n1137\n01:50:45.938 --> 01:50:47.689\n我们一会儿见\n\n1138\n01:50:55.531 --> 01:50:56.532\n好的\n\n1139\n01:51:04.581 --> 01:51:07.334\n赛场上 魔鬼鱼在第一局上半场\n\n1140\n01:51:07.417 --> 01:51:09.461\n三个击球手无一安全到达一垒\n现在游骑兵\n\n1141\n01:51:09.545 --> 01:51:12.631\n试图在第一局下半场进攻得分\n\n1142\n01:51:12.714 --> 01:51:19.012\n亮相的是游骑兵队的中场手\n24号 汤姆·古德温\n\n1143\n01:51:37.906 --> 01:51:40.951\n三个球 一个好球 一个出局 投球\n\n1144\n01:51:41.034 --> 01:51:43.537\n低了 四个球 跑垒员在一垒和二垒\n\n1145\n01:51:43.620 --> 01:51:46.206\n得克萨斯有得分机会\n\n1146\n01:51:46.290 --> 01:51:49.126\n纪念项目的第24页…\n\n1147\n01:51:49.209 --> 01:51:51.837\n投球了 球被甩到中外场\n\n1148\n01:51:51.920 --> 01:51:56.466\n一个安打 跑垒得分\n跑垒员在一垒和二垒\n\n1149\n01:51:56.550 --> 01:52:00.095\n得克萨斯一比零 游骑兵一比零领先\n\n1150\n01:52:00.179 --> 01:52:01.722\n右外场挥击安打\n\n1151\n01:52:01.805 --> 01:52:04.850\n比赛现在一比一平\n\n1152\n01:52:04.900 --> 01:52:09.564\n提醒 魔鬼鱼和游骑兵正在对战\n\n1153\n01:52:09.646 --> 01:52:11.857\n第四局下半场就要开始了\n\n1154\n01:52:11.940 --> 01:52:14.943\n游骑兵一分 魔鬼鱼一分\n\n1155\n01:52:18.238 --> 01:52:20.157\n球又投到地上了\n\n1156\n01:52:20.240 --> 01:52:23.368\n这已经是他投的第三个了\n似乎坦帕湾\n\n1157\n01:52:23.452 --> 01:52:24.745\n该有所行动了\n\n1158\n01:52:24.828 --> 01:52:27.414\n布兰顿 米勒\n\n1159\n01:52:29.416 --> 01:52:30.792\n不 不是你\n\n1160\n01:52:33.170 --> 01:52:35.589\n投球 挥击 球打到了右外野\n\n1161\n01:52:35.672 --> 01:52:38.008\n看起来是附加垒击\n\n1162\n01:52:38.398 --> 01:52:40.064\n一分本垒打 两分本垒打\n\n1163\n01:52:40.594 --> 01:52:44.056\n投球中断 在三垒 三垒出局！\n\n1164\n01:52:44.515 --> 01:52:48.060\n游骑兵三分 魔鬼鱼一分\n这是第六局下半场\n\n1165\n01:52:48.143 --> 01:52:52.147\n棒球史上的今天\n\n1166\n01:52:52.231 --> 01:52:55.484\n跑垒员在一垒和二垒\n这是游骑兵的好机会\n\n1167\n01:52:55.567 --> 01:52:59.738\n这局开始 投球 挥击\n\n1168\n01:52:59.821 --> 01:53:03.534\n一记扣杀冲入左外野 得两分\n\n1169\n01:53:03.617 --> 01:53:06.245\n游骑兵五分 魔鬼鱼一分\n\n1170\n01:53:06.328 --> 01:53:08.163\n得州队打破了僵局\n\n1171\n01:53:15.003 --> 01:53:17.589\n魔鬼鱼和游骑兵周日晚上也有比赛\n\n1172\n01:53:17.673 --> 01:53:20.425\n比赛时间是7:05\n是棒球双赛的第二场比赛\n\n1173\n01:53:20.509 --> 01:53:22.886\n所有十三岁及以下的球迷\n都能得到一顶游骑兵的帽子\n\n1174\n01:53:22.970 --> 01:53:26.014\n比赛时间是周日的7:05\n\n1175\n01:53:27.850 --> 01:53:29.017\n莫里斯！\n\n1176\n01:53:29.768 --> 01:53:31.520\n开始热身\n\n1177\n01:53:37.192 --> 01:53:38.443\n妈妈\n\n1178\n01:53:38.527 --> 01:53:40.737\n他到候补区了\n\n1179\n01:53:41.238 --> 01:53:43.198\n噢 我的天啊\n\n1180\n01:53:47.077 --> 01:53:50.539\n嘿 伙计们 他上了 他上了 他上了\n\n1181\n01:53:50.622 --> 01:53:53.333\n看 他到候补区了 他在那儿 是啊\n\n1182\n01:53:53.417 --> 01:53:54.918\n他看上去不错\n\n1183\n01:53:58.672 --> 01:54:01.008\n来来来 看看\n\n1184\n01:54:02.092 --> 01:54:04.303\n布兰顿试图摆脱满垒困境\n\n1185\n01:54:04.386 --> 01:54:06.305\n挥击 球冲向了他\n\n1186\n01:54:06.388 --> 01:54:09.141\n他取回了球 在前面…\n\n1187\n01:54:09.224 --> 01:54:13.061\n他投球了 又是一记本垒打\n\n1188\n01:54:13.061 --> 01:54:15.980\n得州队两次本垒打\n\n1189\n01:54:16.064 --> 01:54:18.400\n游骑兵大大打开了比赛的局面\n\n1190\n01:54:18.942 --> 01:54:23.363\n布兰顿可能在跑回投手丘时\n速度太快受伤了\n\n1191\n01:54:23.447 --> 01:54:25.782\n吉米·莫里斯还在候补区投球\n\n1192\n01:54:26.674 --> 01:54:28.369\n来自得克萨斯州比格莱克的\n左撇子投手\n\n1193\n01:54:28.449 --> 01:54:29.903\n看 是教练 是教练\n\n1194\n01:54:33.332 --> 01:54:37.419\n-上啊！加油！\n-上啊 教练！\n\n1195\n01:54:37.503 --> 01:54:40.506\n坦帕湾的教练在投手丘查看\n\n1196\n01:54:40.589 --> 01:54:43.717\n看起来似乎魔鬼鱼必须换投手了\n\n1197\n01:54:43.800 --> 01:54:46.970\n莫里斯！你上场吧\n\n1198\n01:55:18.710 --> 01:55:20.629\n加油 教练！\n\n1199\n01:55:45.779 --> 01:55:49.658\n就在三个月前\n他还在给化学考试打分\n\n1200\n01:55:49.741 --> 01:55:54.746\n现在吉米·莫里斯来到了\n大联盟棒球赛的投手丘\n\n1201\n01:55:55.581 --> 01:56:00.961\n比在老家时要更吵一些吧？\n咱们别把事情想得很难\n\n1202\n01:56:01.420 --> 01:56:04.715\n你还记得比赛前你给我看的快球吧？\n\n1203\n01:56:04.798 --> 01:56:08.122\n-我记得\n-我要你投出三个那样的球\n\n1204\n01:56:08.122 --> 01:56:10.496\n为坦帕湾投球\n\n1205\n01:56:11.013 --> 01:56:16.143\n得州人吉米·莫里斯在大联盟\n首次登场\n\n1206\n01:56:18.270 --> 01:56:20.981\n莫里斯要面对的是\n游骑兵的游击手 罗伊斯·克莱顿\n\n1207\n01:56:21.064 --> 01:56:23.442\n罗伊斯后半场非常强劲\n\n1208\n01:56:23.525 --> 01:56:27.362\n而且在整个九月一直如此\n\n1209\n01:56:27.696 --> 01:56:29.281\n加油 爸爸！\n\n1210\n01:56:58.852 --> 01:57:00.729\n-耶！\n-耶！\n\n1211\n01:57:01.839 --> 01:57:04.602\n<i>每小时160公里</i>\n\n1212\n01:57:04.691 --> 01:57:06.777\n再来一个！\n\n1213\n01:57:18.997 --> 01:57:20.332\n第二个好球！\n\n1214\n01:58:36.366 --> 01:58:39.620\n吉米 你投了什么球能够三振出局？\n\n1215\n01:58:44.625 --> 01:58:50.088\n快球 快球 快球\n\n1216\n01:58:50.464 --> 01:58:52.716\n感觉怎么样？\n在大联盟比赛中投球？\n\n1217\n01:58:52.799 --> 01:58:55.552\n-就像我以前希望的那样\n-胳膊感觉怎么样？\n\n1218\n01:59:03.101 --> 01:59:07.689\n我能失陪一下吗？\n对不起 能失陪一下吗？\n\n1219\n01:59:18.116 --> 01:59:19.140\n先生 我不知道你在这儿\n\n1220\n01:59:21.870 --> 01:59:23.872\n这次可没错过\n\n1221\n01:59:30.629 --> 01:59:32.631\n今晚看你…\n\n1222\n01:59:38.971 --> 01:59:41.390\n没几个父亲能有机会这样\n\n1223\n01:59:46.436 --> 01:59:49.481\n我想我错过太多了\n\n1224\n01:59:55.696 --> 01:59:57.114\n我也是\n\n1225\n02:00:03.287 --> 02:00:05.038\n好吧\n\n1226\n02:00:05.664 --> 02:00:07.958\n-爸爸\n-怎么？\n\n1227\n02:00:28.687 --> 02:00:31.273\n谢谢你能来\n\n1228\n02:01:09.895 --> 02:01:12.564\n这是不是意味着我拿不到棒球了？\n\n1229\n02:01:22.366 --> 02:01:25.994\n-我只有这个\n-女孩儿会更糟\n\n1230\n02:01:31.667 --> 02:01:35.045\n作为过去30年来\n年龄最大的新秀 你感觉如何？\n\n1231\n02:01:35.921 --> 02:01:39.466\n不知道 我很累\n\n1232\n02:01:41.343 --> 02:01:42.845\n孩子们呢？\n\n1233\n02:01:42.928 --> 02:01:45.723\n亨特和亨利在一起\n杰茜和卡尔在一起\n\n1234\n02:01:45.723 --> 02:01:49.893\n-别告诉我你把杰茜留给卡尔了\n-卡尔能帮上点儿忙\n" }); }
